"use client";
/**
 * Petal Sign-up: a sign-up card beside a live scene. Petals fall from a blossoming branch into still water, and
 * each one that lands starts a ripple that bends the reflection. An old computer on a stone in the water shows what
 * the form is doing: the product's mark, the email as it is typed, a dot per password character, an error, then a
 * welcome. Every keystroke lets one petal go from the branch, the pointer stirs the air, and a finished sign-up ends
 * in a burst of petals and a gust across the lake.
 *
 * The scene is three.js, loaded only when the card comes near the viewport, paused while it is off screen or the tab
 * is hidden, and it steps its quality down when frames run long. Under reduced motion, with `still`, or without
 * WebGL, the card shows a poster instead. Reduced motion and `still` never load three.js. The default poster is a captured still, with a painted SVG fallback if the image cannot load.
 */
import {
  type CSSProperties,
  type ChangeEvent,
  type FormEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
  useEffect,
  useId,
  useReducer,
  useRef,
  useState,
} from "react";
import {
  INITIAL_SIGNUP,
  type SignupAction,
  type SignupResult,
  type SignupRules,
  type SignupState,
  screenFor,
  signupReducer,
  statusFor,
  validateSignup,
} from "./petal-signup/form";
import { AlertIcon, PROVIDER_ICONS, SunMark } from "./petal-signup/marks";
import {
  ZEPHYR_PETAL_PALETTE,
  ZEPHYR_PETAL_SIGNUP_COLORS,
  type ZephyrPetalPalette,
  type ZephyrPetalSignupColors,
} from "./petal-signup/palette";
import { PetalPoster } from "./petal-signup/poster";
import type { PetalScene, PetalSceneStats } from "./petal-signup/scene.js";
import type { ScreenCopy } from "./petal-signup/screen";
import { resolveSeed } from "./petal-signup/sim";
import { PETAL_SIGNUP_CSS } from "./petal-signup/styles";

export { ZEPHYR_PETAL_PALETTE, ZEPHYR_PETAL_SIGNUP_COLORS };
export type { ZephyrPetalPalette, ZephyrPetalSignupColors };

/** Frame statistics from the live scene. */
export type ZephyrPetalSceneStats = PetalSceneStats;

/** What `onSubmit` resolves to: `{ ok: true }`, or an error for a field or for the whole form. */
export type ZephyrSignupResult = SignupResult;

/** `onSubmit` may also resolve an error message alone, or nothing at all for success. */
export type ZephyrSignupOutcome = SignupResult | string | null | undefined | void;

export interface ZephyrSignupValues {
  /** Trimmed. */
  email: string;
  password: string;
}

export interface ZephyrPetalProvider {
  id: string;
  /** The provider's name on the button. */
  label: string;
  /** Defaults to the built-in icon for `google`, `apple` and `github`. */
  icon?: ReactNode;
}

/** The running scene, for frame statistics and for capturing it frame by frame. */
export interface ZephyrPetalSceneHandle {
  /** Seconds of scene time so far. */
  readonly time: number;
  stats(): ZephyrPetalSceneStats;
  /** Takes the clock from the browser: the scene then moves only when `advance` is called. */
  setManual(on: boolean): void;
  /** Steps the scene by this many seconds and draws a frame. */
  advance(seconds: number): void;
}

export interface ZephyrPetalSignupCopy {
  /** The product's name: beside the mark, on the computer's screen and in the welcome. */
  brand: string;
  /** Under the name on the screen. */
  tagline: string;
  title: string;
  lede: string;
  emailLabel: string;
  emailPlaceholder: string;
  passwordLabel: string;
  /** Under the password; `{min}` becomes the shortest length allowed. */
  passwordHint: string;
  showPassword: string;
  hidePassword: string;
  /** The names screen readers hear for the show and hide button. */
  showPasswordLabel: string;
  hidePasswordLabel: string;
  /** Replaces the whole terms line. By default it links `termsHref` and `privacyHref`. */
  terms?: ReactNode;
  termsLink: string;
  privacyLink: string;
  submit: string;
  pending: string;
  divider: string;
  /** The name screen readers hear for a provider button; `{provider}` becomes its label. */
  providerLabel: string;
  switchPrompt: string;
  switchAction: string;
  successTitle: string;
  /** `{email}` becomes the address. */
  successBody: string;
  successAgain: string;
  /** Read out while the account is being created and once it is. */
  announcePending: string;
  announceSuccess: string;
  emailMissing: string;
  emailInvalid: string;
  passwordMissing: string;
  /** `{min}` becomes the shortest length allowed. */
  passwordShort: string;
  termsMissing: string;
  /** Shown when `onSubmit` throws or rejects. */
  failed: string;
  /** Above the echo on the screen while each field is typed in. */
  screenEmail: string;
  screenPassword: string;
  screenPending: string;
  /** `{brand}` becomes the product's name. */
  screenWelcome: string;
}

export const ZEPHYR_PETAL_SIGNUP_COPY: ZephyrPetalSignupCopy = {
  brand: "Stillwater",
  tagline: "a quiet place to work",
  title: "A little space to begin.",
  lede: "Make room for what matters.",
  emailLabel: "Email",
  emailPlaceholder: "you@example.com",
  passwordLabel: "Password",
  passwordHint: "At least {min} characters.",
  showPassword: "Show",
  hidePassword: "Hide",
  showPasswordLabel: "Show password",
  hidePasswordLabel: "Hide password",
  termsLink: "Terms",
  privacyLink: "Privacy Policy",
  submit: "Create account",
  pending: "Creating account…",
  divider: "or",
  providerLabel: "Continue with {provider}",
  switchPrompt: "Already have an account?",
  switchAction: "Sign in",
  successTitle: "Check your email",
  successBody: "We sent a link to {email}. Open it to finish creating your account.",
  successAgain: "Use a different email",
  announcePending: "Creating your account.",
  announceSuccess: "Account created. Check your email for a link to finish.",
  emailMissing: "Enter your email address.",
  emailInvalid: "Enter an email address like name@example.com.",
  passwordMissing: "Choose a password.",
  passwordShort: "Use at least {min} characters.",
  termsMissing: "Agree to the Terms and Privacy Policy to continue.",
  failed: "Your account wasn't created. Check your connection and try again.",
  screenEmail: "your email",
  screenPassword: "password",
  screenPending: "Setting up your desk",
  screenWelcome: "Welcome to {brand}",
};

export const ZEPHYR_PETAL_PROVIDERS: ZephyrPetalProvider[] = [
  { id: "google", label: "Google" },
  { id: "apple", label: "Apple" },
  { id: "github", label: "GitHub" },
];

const SANS = "Manrope, 'Avenir Next', 'Segoe UI Variable Text', 'Segoe UI', system-ui, sans-serif";
const MONO = "'JetBrains Mono', ui-monospace, 'SF Mono', Menlo, Consolas, monospace";

export interface ZephyrPetalSignupProps {
  /** Form / scene proportions on wide cards. Narrow cards always stack. Defaults to 50-50. */
  split?: "50-50" | "40-60" | "30-70";
  /** Words on the card and on the computer's screen. Anything left out keeps its default. */
  copy?: Partial<ZephyrPetalSignupCopy>;
  /** Sign-in buttons under the form, in order. An empty list hides them and the divider. */
  providers?: ZephyrPetalProvider[];
  /** Called with a provider's id when its button is pressed. */
  onProvider?: (id: string) => void;
  /**
   * Called with the email and password once every check passes. Resolve `{ ok: true }` or nothing for success;
   * `{ ok: false, error, field }` or the message alone shows an error. A throw or rejection shows `copy.failed`.
   */
  onSubmit?: (values: ZephyrSignupValues) => ZephyrSignupOutcome | Promise<ZephyrSignupOutcome>;
  /** Fixes where petals fall. Without one, each visit falls differently. */
  seed?: number;
  /** Petals in the air and on the water at once, 0 to 1200. */
  petalCount?: number;
  /** Multiplies the breeze and its eddies; 0 lets petals fall straight down. 0 to 3. */
  windStrength?: number;
  /**
   * Shown before the scene loads, under reduced motion and without WebGL: an image URL or any element. Defaults to
   * a captured still of the scene. A painted SVG remains as an offline fallback.
   */
  poster?: ReactNode;
  /** Shows the poster only; the scene never loads. */
  still?: boolean;
  /** Distant sky, mountains and far shore. The foreground remains live geometry. */
  backdropUrl?: string;
  /** Multiplies the backdrop colour to match a different lighting palette. */
  backdropTint?: string;
  /** Directory containing color.webp, normal.webp and arm.webp for the CC0 cherry bark. */
  barkTexturePath?: string;
  /** Colours of the scene and the screen. */
  palette?: Partial<ZephyrPetalPalette>;
  /** Colours of the card. */
  colors?: Partial<ZephyrPetalSignupColors>;
  /** Font stacks for the card and the screen's text, and for the screen's echo. */
  fonts?: { sans?: string; mono?: string; display?: string };
  minPasswordLength?: number;
  termsHref?: string;
  privacyHref?: string;
  signInHref?: string;
  /** Receives the scene once it runs, and null when it stops. */
  onScene?: (scene: ZephyrPetalSceneHandle | null) => void;
  className?: string;
  style?: CSSProperties;
}

const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value));

function settled(outcome: unknown, failed: string): SignupResult {
  if (typeof outcome === "string") return { ok: false, error: outcome || failed };
  if (outcome && typeof outcome === "object" && "ok" in outcome) {
    const result = outcome as SignupResult;
    if (result.ok) return { ok: true };
    return { ok: false, error: result.error || failed, field: result.field };
  }
  return { ok: true };
}

/** null until the first effect, so the server and the first paint agree and nothing loads early. */
function useReducedMotion(): boolean | null {
  const [reduce, setReduce] = useState<boolean | null>(null);
  useEffect(() => {
    const query =
      typeof window.matchMedia === "function"
        ? window.matchMedia("(prefers-reduced-motion: reduce)")
        : null;
    if (!query) {
      setReduce(false);
      return;
    }
    const update = () => setReduce(query.matches);
    update();
    query.addEventListener?.("change", update);
    return () => query.removeEventListener?.("change", update);
  }, []);
  return reduce;
}

const isPhone = () =>
  typeof window.matchMedia === "function" &&
  window.matchMedia("(pointer: coarse)").matches &&
  Math.min(window.screen.width, window.screen.height) < 820;

function withEmail(template: string, email: string): ReactNode[] {
  return template
    .split("{email}")
    .flatMap((part, i) => (i === 0 ? [part] : [<strong key={i}>{email}</strong>, part]));
}

export function ZephyrPetalSignup({
  copy,
  split = "50-50",
  providers = ZEPHYR_PETAL_PROVIDERS,
  onProvider,
  onSubmit,
  seed,
  petalCount = 440,
  windStrength = 1,
  poster = "https://myzeusui.com/assets/zephyr/petal-signup-poster.webp",
  still = false,
  backdropUrl = "https://myzeusui.com/assets/zephyr/lakeside-sunset.webp",
  backdropTint = "#ffffff",
  barkTexturePath = "https://myzeusui.com/assets/zephyr/bark/",
  palette: paletteProp,
  colors: colorsProp,
  fonts,
  minPasswordLength = 8,
  termsHref = "#",
  privacyHref = "#",
  signInHref = "#",
  onScene,
  className,
  style,
}: ZephyrPetalSignupProps) {
  const text = { ...ZEPHYR_PETAL_SIGNUP_COPY, ...copy };
  const palette = { ...ZEPHYR_PETAL_PALETTE, ...paletteProp };
  const colors = { ...ZEPHYR_PETAL_SIGNUP_COLORS, ...colorsProp };
  const sans = fonts?.sans ?? SANS;
  const mono = fonts?.mono ?? MONO;
  const rules: SignupRules = {
    emailMissing: text.emailMissing,
    emailInvalid: text.emailInvalid,
    passwordMissing: text.passwordMissing,
    passwordShort: text.passwordShort,
    terms: text.termsMissing,
    failed: text.failed,
    minPassword: Math.max(1, Math.floor(minPasswordLength)),
  };
  const rulesRef = useRef(rules);
  rulesRef.current = rules;
  const [state, dispatch] = useReducer(
    (current: SignupState, action: SignupAction) =>
      signupReducer(current, action, rulesRef.current),
    INITIAL_SIGNUP,
  );
  const [reveal, setReveal] = useState(false);
  const [live, setLive] = useState(false);
  const [posterFailed, setPosterFailed] = useState<string | null>(null);
  const reduce = useReducedMotion();

  const uid = useId();
  const ids = {
    title: `${uid}title`,
    email: `${uid}email`,
    emailError: `${uid}email-error`,
    password: `${uid}password`,
    passwordHint: `${uid}password-hint`,
    passwordError: `${uid}password-error`,
    terms: `${uid}terms`,
    termsError: `${uid}terms-error`,
    formError: `${uid}form-error`,
  };

  const titleRef = useRef<HTMLHeadingElement>(null);
  const emailRef = useRef<HTMLInputElement>(null);
  const passwordRef = useRef<HTMLInputElement>(null);
  const termsRef = useRef<HTMLInputElement>(null);
  const hostRef = useRef<HTMLDivElement>(null);
  const sceneRef = useRef<PetalScene | null>(null);
  const onSceneRef = useRef(onScene);
  onSceneRef.current = onScene;
  const attempt = useRef(0);
  const focusInvalid = useRef(false);
  const focusEmail = useRef(false);
  const phaseRef = useRef(state.phase);
  const pointerRef = useRef<{ x: number; y: number; t: number } | null>(null);

  const screen = screenFor(state);
  const screenRef = useRef(screen);
  screenRef.current = screen;

  const screenCopy: ScreenCopy = {
    brand: text.brand,
    tagline: text.tagline,
    email: text.screenEmail,
    password: text.screenPassword,
    pending: text.screenPending,
    welcome: text.screenWelcome.replace("{brand}", text.brand),
  };
  const count = Math.round(clamp(petalCount, 0, 1200));
  const wind = clamp(windStrength, 0, 3);
  const config = {
    seed,
    count,
    wind,
    palette,
    screenCopy,
    sans,
    mono,
    backdropUrl,
    backdropTint,
    barkTexturePath,
  };
  const configRef = useRef(config);
  configRef.current = config;
  const sceneKey = JSON.stringify(config);

  // The scene: loaded near the viewport, paused off screen and in hidden tabs, rebuilt when its settings change.
  useEffect(() => {
    const host = hostRef.current;
    if (still || reduce !== false || !host) return;
    const options = configRef.current;
    let cancelled = false;
    let loading = false;
    let scene: PetalScene | null = null;
    let canvas: HTMLCanvasElement | null = null;
    let visible = typeof IntersectionObserver === "undefined";
    const run = () => scene?.setRunning(visible && document.visibilityState !== "hidden");
    const start = () => {
      if (loading) return;
      loading = true;
      import("./petal-signup/scene.js").then(
        ({ PetalScene: Scene }) => {
          if (cancelled) return;
          canvas = document.createElement("canvas");
          canvas.className = "zps-canvas";
          canvas.setAttribute("aria-hidden", "true");
          host.append(canvas);
          scene = Scene.create(canvas, {
            seed: resolveSeed(options.seed),
            petalCount: options.count,
            wind: options.wind,
            palette: options.palette,
            screenCopy: options.screenCopy,
            fonts: { sans: options.sans, mono: options.mono },
            phone: isPhone(),
            backdropUrl: options.backdropUrl,
            backdropTint: options.backdropTint,
            barkTexturePath: options.barkTexturePath,
          });
          if (!scene) {
            canvas.remove();
            return;
          }
          sceneRef.current = scene;
          scene.setScreen(screenRef.current);
          const box = host.getBoundingClientRect();
          scene.setSize(box.width, box.height);
          setLive(true);
          onSceneRef.current?.(scene);
          run();
        },
        () => {
          // The chunk failed to load: the poster stays.
        },
      );
    };
    const io =
      typeof IntersectionObserver === "undefined"
        ? null
        : new IntersectionObserver(
            (entries) => {
              visible = entries.some((entry) => entry.isIntersecting);
              if (visible) start();
              run();
            },
            { rootMargin: "200px 0px" },
          );
    if (io) io.observe(host);
    else start();
    const ro =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver((entries) => {
            const box = entries[0]?.contentRect;
            if (box && scene) scene.setSize(box.width, box.height);
          });
    ro?.observe(host);
    document.addEventListener("visibilitychange", run);
    return () => {
      cancelled = true;
      io?.disconnect();
      ro?.disconnect();
      document.removeEventListener("visibilitychange", run);
      if (scene) {
        scene.dispose();
        onSceneRef.current?.(null);
      }
      canvas?.remove();
      sceneRef.current = null;
      setLive(false);
    };
  }, [still, reduce, sceneKey]);

  // The screen follows the form; the scene ignores a picture it already shows.
  useEffect(() => {
    sceneRef.current?.setScreen(screen);
  });

  useEffect(() => {
    const before = phaseRef.current;
    phaseRef.current = state.phase;
    if (state.phase === "success" && before !== "success") {
      sceneRef.current?.celebrate();
      titleRef.current?.focus();
    }
    if (focusEmail.current && state.phase === "idle") {
      focusEmail.current = false;
      emailRef.current?.focus();
    }
  }, [state.phase]);

  // After a failed submit, focus goes to the first field to fix.
  useEffect(() => {
    if (!focusInvalid.current || state.phase !== "error") return;
    focusInvalid.current = false;
    const { errors } = state;
    const field = errors.email
      ? emailRef
      : errors.password
        ? passwordRef
        : errors.terms
          ? termsRef
          : null;
    field?.current?.focus();
  }, [state]);

  useEffect(
    () => () => {
      attempt.current = -1;
    },
    [],
  );

  const pending = state.phase === "pending";
  const success = state.phase === "success";
  const errors = state.errors;

  const edit = (field: "email" | "password") => (event: ChangeEvent<HTMLInputElement>) => {
    if (pending || success) return;
    dispatch({ type: "edit", field, value: event.target.value });
    // The keyboard in the scene presses the key typed into the email; for the password, a key at random.
    const data = (event.nativeEvent as { data?: unknown }).data;
    sceneRef.current?.keystroke(
      field === "email" && typeof data === "string" && data.length === 1 ? data : undefined,
    );
  };

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (pending || success) return;
    const invalid = Object.keys(validateSignup(state, rules)).length > 0;
    dispatch({ type: "submit" });
    if (invalid) {
      focusInvalid.current = true;
      return;
    }
    const run = ++attempt.current;
    let result: SignupResult;
    try {
      result = settled(
        await onSubmit?.({ email: state.email.trim(), password: state.password }),
        rules.failed,
      );
    } catch {
      result = { ok: false, error: rules.failed };
    }
    if (run !== attempt.current) return;
    focusInvalid.current = !result.ok;
    dispatch({ type: "settle", result });
  };

  const startOver = () => {
    focusEmail.current = true;
    setReveal(false);
    dispatch({ type: "reset" });
  };

  const onPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    const scene = sceneRef.current;
    if (!scene) return;
    const box = event.currentTarget.getBoundingClientRect();
    const x = ((event.clientX - box.left) / box.width) * 2 - 1;
    const y = 1 - ((event.clientY - box.top) / box.height) * 2;
    const t = event.timeStamp / 1000;
    const last = pointerRef.current;
    pointerRef.current = { x, y, t };
    if (!last) scene.pointer(x, y, 0, 0, 0);
    else scene.pointer(x, y, x - last.x, y - last.y, Math.max(1 / 240, t - last.t));
  };
  const onPointerLeave = () => {
    pointerRef.current = null;
    sceneRef.current?.pointer(0, 0, 0, 0, 0);
  };

  const status = statusFor(state, { pending: text.announcePending, success: text.announceSuccess });
  const terms = text.terms ?? (
    <>
      I agree to the <a href={termsHref}>{text.termsLink}</a> and{" "}
      <a href={privacyHref}>{text.privacyLink}</a>.
    </>
  );
  // An image poster that fails to load falls back to the painted one.
  const posterNode =
    poster === undefined || (typeof poster === "string" && posterFailed === poster) ? (
      <PetalPoster palette={palette} brand={text.brand} tagline={text.tagline} font={sans} />
    ) : typeof poster === "string" ? (
      <img src={poster} alt="" decoding="async" onError={() => setPosterFailed(poster)} />
    ) : (
      poster
    );
  const vars = {
    "--zps-form-share": split === "30-70" ? "3fr" : split === "40-60" ? "4fr" : "5fr",
    "--zps-scene-share": split === "30-70" ? "7fr" : split === "40-60" ? "6fr" : "5fr",
    "--zps-card": colors.card,
    "--zps-field": colors.field,
    "--zps-ink": colors.ink,
    "--zps-muted": colors.muted,
    "--zps-line": colors.line,
    "--zps-button": colors.button,
    "--zps-button-text": colors.buttonText,
    "--zps-focus": colors.focus,
    "--zps-error": colors.error,
    "--zps-backdrop": colors.backdrop,
    "--zps-sans": sans,
    "--zps-display": fonts?.display ?? "Georgia, 'Times New Roman', serif",
  } as CSSProperties;
  const passwordDescribedBy = errors.password ? ids.passwordError : ids.passwordHint;

  return (
    <div
      className={className ? `zps ${className}` : "zps"}
      style={{ ...vars, ...style }}
      data-scene={live ? "live" : "poster"}
      data-phase={state.phase}
      data-split={split}
    >
      <style>{PETAL_SIGNUP_CSS}</style>
      <div className="zps-card">
        <div className="zps-side">
          <div className="zps-brand">
            <SunMark size={24} sun={colors.mark} line={colors.ink} />
            <span>{text.brand}</span>
          </div>
          <div className="zps-main">
            <div>
              <h2 ref={titleRef} id={ids.title} className="zps-title" tabIndex={-1}>
                {success ? text.successTitle : text.title}
              </h2>
              <p className="zps-lede">
                {success ? withEmail(text.successBody, state.email.trim()) : text.lede}
              </p>
            </div>
            {/* The form stays laid out under the success panel, so the card keeps its height. */}
            <div className="zps-stack">
              <div
                className="zps-entry"
                aria-hidden={success ? true : undefined}
                inert={success ? true : undefined}
                style={success ? { visibility: "hidden" } : undefined}
              >
                <form className="zps-form" noValidate onSubmit={submit} aria-labelledby={ids.title}>
                  <div className="zps-field">
                    <label className="zps-label" htmlFor={ids.email}>
                      {text.emailLabel}
                    </label>
                    <input
                      ref={emailRef}
                      id={ids.email}
                      className="zps-input"
                      type="email"
                      name="email"
                      autoComplete="email"
                      inputMode="email"
                      autoCapitalize="none"
                      spellCheck={false}
                      required
                      placeholder={text.emailPlaceholder}
                      value={state.email}
                      readOnly={pending}
                      aria-invalid={errors.email ? true : undefined}
                      aria-describedby={errors.email ? ids.emailError : undefined}
                      onChange={edit("email")}
                      onFocus={() => dispatch({ type: "focus", field: "email" })}
                      onBlur={() => dispatch({ type: "focus", field: null })}
                    />
                    {errors.email ? (
                      <p id={ids.emailError} className="zps-error">
                        <AlertIcon />
                        {errors.email}
                      </p>
                    ) : null}
                  </div>
                  <div className="zps-field">
                    <label className="zps-label" htmlFor={ids.password}>
                      {text.passwordLabel}
                    </label>
                    <div className="zps-secret">
                      <input
                        ref={passwordRef}
                        id={ids.password}
                        className="zps-input"
                        type={reveal ? "text" : "password"}
                        name="password"
                        autoComplete="new-password"
                        autoCapitalize="none"
                        spellCheck={false}
                        required
                        value={state.password}
                        readOnly={pending}
                        aria-invalid={errors.password ? true : undefined}
                        aria-describedby={passwordDescribedBy}
                        onChange={edit("password")}
                        onFocus={() => dispatch({ type: "focus", field: "password" })}
                        onBlur={() => dispatch({ type: "focus", field: null })}
                      />
                      <button
                        type="button"
                        className="zps-reveal"
                        aria-controls={ids.password}
                        aria-label={reveal ? text.hidePasswordLabel : text.showPasswordLabel}
                        onClick={() => setReveal((on) => !on)}
                      >
                        {reveal ? text.hidePassword : text.showPassword}
                      </button>
                    </div>
                    {errors.password ? (
                      <p id={ids.passwordError} className="zps-error">
                        <AlertIcon />
                        {errors.password}
                      </p>
                    ) : (
                      <p id={ids.passwordHint} className="zps-hint">
                        {text.passwordHint.replace("{min}", String(rules.minPassword))}
                      </p>
                    )}
                  </div>
                  <div className="zps-terms">
                    <input
                      ref={termsRef}
                      id={ids.terms}
                      className="zps-check"
                      type="checkbox"
                      name="terms"
                      required
                      checked={state.terms}
                      aria-invalid={errors.terms ? true : undefined}
                      aria-describedby={errors.terms ? ids.termsError : undefined}
                      onChange={(event) => dispatch({ type: "terms", value: event.target.checked })}
                    />
                    <label htmlFor={ids.terms}>{terms}</label>
                    {errors.terms ? (
                      <p id={ids.termsError} className="zps-error">
                        <AlertIcon />
                        {errors.terms}
                      </p>
                    ) : null}
                  </div>
                  {errors.form ? (
                    <p id={ids.formError} className="zps-alert">
                      <AlertIcon />
                      {errors.form}
                    </p>
                  ) : null}
                  <button
                    type="submit"
                    className="zps-submit"
                    aria-disabled={pending ? true : undefined}
                    aria-describedby={errors.form ? ids.formError : undefined}
                  >
                    {pending ? <span className="zps-spinner" aria-hidden="true" /> : null}
                    <span>{pending ? text.pending : text.submit}</span>
                  </button>
                </form>
                {providers.length > 0 ? (
                  <>
                    <div className="zps-or">{text.divider}</div>
                    <div className="zps-providers">
                      {providers.map((provider) => (
                        <button
                          key={provider.id}
                          type="button"
                          className="zps-provider"
                          disabled={pending}
                          aria-label={text.providerLabel.replace("{provider}", provider.label)}
                          onClick={() => onProvider?.(provider.id)}
                        >
                          {provider.icon ?? PROVIDER_ICONS[provider.id] ?? null}
                          <span>{provider.label}</span>
                        </button>
                      ))}
                    </div>
                  </>
                ) : null}
              </div>
              {success ? (
                <div className="zps-done">
                  <button type="button" className="zps-again" onClick={startOver}>
                    {text.successAgain}
                  </button>
                </div>
              ) : null}
            </div>
          </div>
          <p className="zps-switch">
            {text.switchPrompt} <a href={signInHref}>{text.switchAction}</a>
          </p>
          <p className="zps-sr" role="status">
            {status}
          </p>
        </div>
        <div
          ref={hostRef}
          className="zps-scene"
          aria-hidden="true"
          onPointerMove={onPointerMove}
          onPointerLeave={onPointerLeave}
        >
          <div className="zps-poster">{posterNode}</div>
        </div>
      </div>
    </div>
  );
}

