import * as THREE from "three";

// Sakura Bark, Charlotte Baglioni / Poly Haven, CC0. Scan covers 1.6 × 1.6 m.
// https://polyhaven.com/a/sakura_bark — provenance in design/zephyr-r259-bark/.
// Shared rest-space projection keeps the texture continuous across every tube,
// without stretching the scan along short twigs or moving it during the sway.
const PROJECTION = `
varying vec3 vBarkPosition;
varying vec3 vBarkNormal;
varying mat3 vBarkNormalMatrix;
vec3 barkWeights(vec3 n) {
  vec3 w=pow(abs(n),vec3(4.)); return w / max(dot(w,vec3(1.)),.0001);
}
vec4 barkSample(sampler2D tex, vec3 p, vec3 n, vec3 w) {
  return texture2D(tex,vec2(-p.z*sign(n.x),p.y))*w.x
    +texture2D(tex,vec2(p.x,-p.z*sign(n.y)))*w.y
    +texture2D(tex,vec2(p.x*sign(n.z),p.y))*w.z;
}
float barkNoise(vec3 p) {
  return .5+.22*sin(p.x*11.+sin(p.y*9.))*sin(p.z*13.-p.y*5.)
    +.13*sin(p.x*43.+p.y*31.)*sin(p.z*37.+p.y*17.);
}
`;

export function createBarkMaterial({
  path,
  tint,
  isDisposed,
  onLoad,
  loader = new THREE.TextureLoader(),
}) {
  const material = new THREE.MeshStandardMaterial({ color: "#4d3931", roughness: 0.95 });
  material.userData.barkReady = false;
  const pending = [];
  let loaded = 0;
  const finish = () => {
    if (++loaded !== 3 || isDisposed()) return;
    material.map = pending[0];
    material.normalMap = pending[1];
    material.roughnessMap = material.aoMap = pending[2];
    material.aoMapIntensity = 0.75;
    // Preserve palette control without multiplying the scan by the old dark tan.
    material.color.set(tint).lerp(new THREE.Color("#ffffff"), 0.88);
    material.userData.barkReady = true;
    material.needsUpdate = true;
    onLoad();
  };
  const base = (path || "https://myzeusui.com/assets/zephyr/bark/").replace(/\/?$/, "/");
  for (const [i, file] of ["color.webp", "normal.webp", "arm.webp"].entries()) {
    const texture = loader.load(
      base + file,
      (ready) => {
        if (isDisposed()) {
          ready.dispose();
          return;
        }
        finish();
      },
      undefined,
      () => {
        /* Retain the matte fallback if a host omits an asset. */
      },
    );
    texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
    texture.anisotropy = 4;
    texture.colorSpace = i === 0 ? THREE.SRGBColorSpace : THREE.NoColorSpace;
    pending.push(texture);
  }
  // Covers both completed maps and in-flight loads when unmount wins the race.
  material.addEventListener("dispose", () => pending.forEach((texture) => texture.dispose()));
  material.onBeforeCompile = (shader) => {
    shader.vertexShader =
      `varying vec3 vBarkPosition; varying vec3 vBarkNormal;
      varying mat3 vBarkNormalMatrix;\n` + shader.vertexShader;
    shader.vertexShader = shader.vertexShader.replace(
      "#include <begin_vertex>",
      `
      #include <begin_vertex>
      vBarkPosition=position+vec3(1.52,.27,-.38);
      vBarkNormal=normal;
      vBarkNormalMatrix=normalMatrix;
    `,
    );
    shader.fragmentShader = PROJECTION + shader.fragmentShader;
    shader.fragmentShader = shader.fragmentShader.replace(
      "#include <map_fragment>",
      `
      vec3 barkN=normalize(vBarkNormal), barkW=barkWeights(barkN);
      vec3 barkP=vBarkPosition/1.6;
      float barkGrowth=(1.-smoothstep(.23,.67,vBarkPosition.y))
        *smoothstep(.35,.69,barkNoise(vBarkPosition*2.3));
      // Damp, occluded bark continues over the root flares. Their sun-facing
      // facets should not read as a separate cream-coloured stump.
      float barkFoot=1.-smoothstep(.28,.72,vBarkPosition.y);
      float barkRoot=barkFoot*(1.-smoothstep(1.63,1.79,vBarkPosition.x));
      float barkJoin=exp(-length(vBarkPosition-vec3(1.43,.99,-.32))*16.)
        +exp(-length(vBarkPosition-vec3(1.12,1.47,-.18))*20.);
      #ifdef USE_MAP
        diffuseColor *= barkSample(map,barkP,barkN,barkW);
      #endif
      vec3 barkSurface=vec3(1.,.95,0.);
      #ifdef USE_ROUGHNESSMAP
        barkSurface=barkSample(roughnessMap,barkP,barkN,barkW).rgb;
      #endif
      diffuseColor.rgb*=mix(.78,1.,barkSurface.r);
      // A low, irregular moss mask is part of the bark, never a decal.
      diffuseColor.rgb *= mix(vec3(1.),vec3(.48,.65,.27),barkGrowth*.72);
      diffuseColor.rgb *= mix(vec3(1.),vec3(.55,.47,.39),barkFoot);
      diffuseColor.rgb *= mix(1.,.3,barkRoot);
      diffuseColor.rgb *= mix(vec3(.85,.74,.69),vec3(1.06,1.06,1.02),barkNoise(vBarkPosition*1.7))
        * (1.-min(.35,barkJoin*.4))
        * mix(.64,1.,smoothstep(.12,.43,vBarkPosition.y));
    `,
    );
    shader.fragmentShader = shader.fragmentShader.replace(
      "#include <roughnessmap_fragment>",
      `
      float roughnessFactor=roughness;
      #ifdef USE_ROUGHNESSMAP
        roughnessFactor*=clamp(barkSurface.g,.56,1.);
      #endif
      roughnessFactor=mix(roughnessFactor,.98,barkGrowth);
      roughnessFactor=mix(roughnessFactor,1.,barkFoot);
    `,
    );
    shader.fragmentShader = shader.fragmentShader.replace(
      "#include <normal_fragment_maps>",
      `
      #ifdef USE_NORMALMAP
        vec3 nx=texture2D(normalMap,vec2(-barkP.z*sign(barkN.x),barkP.y)).xyz*2.-1.;
        vec3 ny=texture2D(normalMap,vec2(barkP.x,-barkP.z*sign(barkN.y))).xyz*2.-1.;
        vec3 nz=texture2D(normalMap,vec2(barkP.x*sign(barkN.z),barkP.y)).xyz*2.-1.;
        nx.xy*=1.6; ny.xy*=1.6; nz.xy*=1.6;
        // Whiteout blends preserve the tube's curved normal with a neutral map.
        vec3 tx=vec3(barkN.x*nx.z,barkN.y+nx.y,barkN.z-nx.x*sign(barkN.x));
        vec3 ty=vec3(barkN.x+ny.x,barkN.y*ny.z,barkN.z-ny.y*sign(barkN.y));
        vec3 tz=vec3(barkN.x+nz.x*sign(barkN.z),barkN.y+nz.y,barkN.z*nz.z);
        normal=normalize(vBarkNormalMatrix*normalize(tx*barkW.x+ty*barkW.y+tz*barkW.z));
      #endif
    `,
    );
    shader.fragmentShader = shader.fragmentShader.replace(
      "#include <aomap_fragment>",
      `
      #ifdef USE_AOMAP
        float ambientOcclusion=mix(1.,barkSurface.r,aoMapIntensity);
        reflectedLight.indirectDiffuse*=ambientOcclusion;
        reflectedLight.indirectSpecular*=ambientOcclusion;
      #endif
    `,
    );
  };
  material.customProgramCacheKey = () => "zephyr-sakura-bark-2";
  return material;
}

// @zeus-internal
/**
 * The sign-up form as plain data: its states, the checks on each field and what the computer's screen shows in
 * each state. No React here, so the tests can drive it directly.
 *
 * idle → typing → pending → success, with error reachable from a failed check or a failed submit. Editing after an
 * error goes back to typing. The screen never receives the password, only its length.
 */

export type SignupPhase = "idle" | "typing" | "pending" | "error" | "success";
export type SignupField = "email" | "password" | "terms";
export type SignupErrors = Partial<Record<SignupField | "form", string>>;

/** What `onSubmit` resolves to. An error names the field it belongs to, or the whole form. */
export type SignupResult = { ok: true } | { ok: false; error: string; field?: "email" | "password" };

export interface SignupRules {
  emailMissing: string;
  emailInvalid: string;
  passwordMissing: string;
  /** `{min}` becomes the minimum length. */
  passwordShort: string;
  terms: string;
  /** Shown when `onSubmit` rejects instead of resolving. */
  failed: string;
  minPassword: number;
}

export interface SignupState {
  phase: SignupPhase;
  email: string;
  password: string;
  terms: boolean;
  focus: "email" | "password" | null;
  errors: SignupErrors;
  /** Set by the first submit; from then on each field is checked as it changes. */
  checked: boolean;
}

export type SignupAction =
  | { type: "focus"; field: "email" | "password" | null }
  | { type: "edit"; field: "email" | "password"; value: string }
  | { type: "terms"; value: boolean }
  | { type: "submit" }
  | { type: "settle"; result: SignupResult }
  | { type: "reset" };

export const INITIAL_SIGNUP: SignupState = {
  phase: "idle",
  email: "",
  password: "",
  terms: false,
  focus: null,
  errors: {},
  checked: false,
};

const EMAIL = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)*\.[^\s@.]{2,}$/;

/** The checks a submit runs: an error per field, or none. */
export function validateSignup(
  values: Pick<SignupState, "email" | "password" | "terms">,
  rules: SignupRules,
): Partial<Record<SignupField, string>> {
  const errors: Partial<Record<SignupField, string>> = {};
  const email = values.email.trim();
  if (!email) errors.email = rules.emailMissing;
  else if (!EMAIL.test(email)) errors.email = rules.emailInvalid;
  if (!values.password) errors.password = rules.passwordMissing;
  else if (values.password.length < rules.minPassword)
    errors.password = rules.passwordShort.replace("{min}", String(rules.minPassword));
  if (!values.terms) errors.terms = rules.terms;
  return errors;
}

const busy = (state: SignupState) => state.phase === "pending" || state.phase === "success";
const restingPhase = (state: Pick<SignupState, "email" | "password" | "focus">): SignupPhase =>
  state.focus || state.email || state.password ? "typing" : "idle";

/** One field's error after a change, once the form has been submitted. */
function recheck(state: SignupState, field: SignupField, rules: SignupRules): SignupErrors {
  const next: SignupErrors = { ...state.errors };
  delete next.form;
  if (!state.checked) return next;
  const found = validateSignup(state, rules)[field];
  if (found) next[field] = found;
  else delete next[field];
  return next;
}

export function signupReducer(state: SignupState, action: SignupAction, rules: SignupRules): SignupState {
  switch (action.type) {
    case "focus": {
      const next = { ...state, focus: action.field };
      if (busy(state) || state.phase === "error") return next;
      return { ...next, phase: restingPhase(next) };
    }
    case "edit": {
      if (busy(state)) return state;
      const next: SignupState = { ...state, [action.field]: action.value };
      return { ...next, phase: "typing", errors: recheck(next, action.field, rules) };
    }
    case "terms": {
      if (busy(state)) return state;
      const next: SignupState = { ...state, terms: action.value };
      const phase = state.phase === "error" ? "typing" : state.phase;
      return { ...next, phase, errors: recheck(next, "terms", rules) };
    }
    case "submit": {
      if (busy(state)) return state;
      const errors = validateSignup(state, rules);
      if (Object.keys(errors).length > 0) return { ...state, phase: "error", errors, checked: true };
      return { ...state, phase: "pending", errors: {}, checked: true };
    }
    case "settle": {
      if (state.phase !== "pending") return state;
      if (action.result.ok) return { ...state, phase: "success", errors: {} };
      const field = action.result.field ?? "form";
      return { ...state, phase: "error", errors: { [field]: action.result.error || rules.failed } };
    }
    case "reset":
      return INITIAL_SIGNUP;
  }
}

/** The first error to show on the screen and to announce. */
export function firstError(state: SignupState): string {
  const e = state.errors;
  return e.form ?? e.email ?? e.password ?? e.terms ?? "";
}

/** What the computer's screen shows. The password reaches it only as a length. */
export type ScreenState =
  | { kind: "logo" }
  | { kind: "email"; text: string }
  | { kind: "password"; length: number }
  | { kind: "pending" }
  | { kind: "error"; message: string }
  | { kind: "welcome" };

export function screenFor(state: SignupState): ScreenState {
  switch (state.phase) {
    case "pending":
      return { kind: "pending" };
    case "success":
      return { kind: "welcome" };
    case "error":
      return { kind: "error", message: firstError(state) };
    default:
      if (state.focus === "email") return { kind: "email", text: state.email };
      if (state.focus === "password") return { kind: "password", length: state.password.length };
      return { kind: "logo" };
  }
}

/** Two screen states are the same picture. */
export function sameScreen(a: ScreenState, b: ScreenState): boolean {
  if (a.kind !== b.kind) return false;
  if (a.kind === "email" && b.kind === "email") return a.text === b.text;
  if (a.kind === "password" && b.kind === "password") return a.length === b.length;
  if (a.kind === "error" && b.kind === "error") return a.message === b.message;
  return true;
}

/** The line read out to screen readers: progress, the outcome, or the first thing to fix. Quiet while typing. */
export function statusFor(state: SignupState, copy: { pending: string; success: string }): string {
  if (state.phase === "pending") return copy.pending;
  if (state.phase === "success") return copy.success;
  if (state.phase === "error") return firstError(state);
  return "";
}

