/** Keys in four rows across the keyboard's top, which narrows away from the viewer. */
const KEYS = Array.from({ length: 4 }, (_, row) => {
  const f = (row + 0.6) / 4.4;
  const left = 190 - 8 * f;
  const right = 378 + 8 * f;
  const count = 16;
  const pitch = (right - left) / count;
  return Array.from({ length: count }, (_, k) => ({ x: left + k * pitch + 0.8, y: 437.6 + 21 * f - 1.6, w: pitch - 1.6, row, k }));
}).flat();

export function PetalPoster({
  palette,
  title,
  brand,
  tagline,
  font,
}: {
  palette: ZephyrPetalPalette;
  title?: string;
  /** Shown on the computer's screen, as the live scene does when idle. */
  brand?: string;
  tagline?: string;
  font?: string;
}) {
  const id = useId().replace(/[^a-zA-Z0-9_-]/g, "");
  const p = palette;
  const ref = (name: string) => `url(#${id}-${name})`;
  const top = mixHex(mixHex(p.horizon, p.glow, 0.2), p.sky, 0.12);
  const haze = mixHex(p.horizon, "#ffffff", 0.22);
  const far = mixHex(p.hills[0], p.horizon, 0.72);
  const mid = mixHex(p.hills[1], p.horizon, 0.64);
  const shade = mixHex(p.computer, p.sky, 0.38);
  const lit = mixHex(p.computer, "#ffffff", 0.28);
  const dark = "#2a2826";
  const keyTop = mixHex(p.keys, "#ffffff", 0.4);
  return (
