// @zeus-internal
/**
 * The scene beside the petal sign-up form: a still lake at sunset, a granite ledge in the water with an old computer
 * on it, a blossoming branch overhead and the petals of PetalSim falling through it all.
 *
 * Every foreground model is built here from three.js primitives and shaders. A generated image supplies the distant landscape. The water reflects the scene
 * through a mirror camera drawn at reduced resolution, and each petal that lands starts a ripple that bends the
 * reflection. The sun stays aligned with the image; its colour changes only subtly. When frames run long the reflection drops to a
 * quarter of the pixels, then the petals thin out.
 */
import * as THREE from "three";
import { createBarkMaterial } from "./bark.js";
import { sameScreen } from "./form";
import { SCREEN_SIZE, drawMark, drawScreen, screenMoves } from "./screen";
import {
  Noise3,
  PARTS,
  PETAL_MODES,
  PETAL_STEP,
  PLACE,
  PetalSim,
  seededRandom,
  stoneHeight,
} from "./sim";

const TAU = Math.PI * 2;
const RIPPLES = 24;
const PETAL_LENGTH = 0.035;
const lerp = (a, b, t) => a + (b - a) * t;
const EYE = new THREE.Vector3(0.55, 0.85, 2.85);
const AT = new THREE.Vector3(0.95, 0.75, -0.2);
const SCRATCH = new THREE.Vector3();

/* ---------- geometry ---------- */

/** A cherry petal one unit long: cupped across, curled along, with a notch at the tip, centred on its middle. */
function petalGeometry(along = 6, across = 4) {
  const positions = [];
  const uvs = [];
  const index = [];
  for (let i = 0; i <= along; i++) {
    const u = i / along;
    const half = 0.33 * Math.sin(Math.PI * u ** 0.65 * 0.9) + 0.025 * (1 - u);
    for (let j = 0; j <= across; j++) {
      const v = (j / across) * 2 - 1;
      const x = v * half;
      const y = u - 0.13 * u ** 5 * (1 - v * v) - 0.5;
      const z = 0.12 * v * v * Math.sin(Math.PI * u) - 0.09 * u * u;
      positions.push(x, y, z);
      uvs.push(j / across, u);
    }
  }
  const row = across + 1;
  for (let i = 0; i < along; i++)
    for (let j = 0; j < across; j++) {
      const a = i * row + j;
      index.push(a, a + 1, a + row, a + 1, a + row + 1, a + row);
    }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  g.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  g.setIndex(index);
  g.computeVertexNormals();
  return g;
}

/** Joins indexed or plain geometries with position, normal and uv into one plain geometry. */
function joinGeometries(list) {
  const parts = list.map((g) => (g.index ? g.toNonIndexed() : g));
  const join = (name, size) => {
    const total = parts.reduce((n, g) => n + g.attributes.position.count, 0);
    const out = new Float32Array(total * size);
    let at = 0;
    for (const g of parts) {
      const attr = g.attributes[name];
      if (attr) out.set(attr.array.subarray(0, g.attributes.position.count * size), at);
      at += g.attributes.position.count * size;
    }
    return new THREE.BufferAttribute(out, size);
  };
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", join("position", 3));
  g.setAttribute("normal", join("normal", 3));
  g.setAttribute("uv", join("uv", 2));
  for (const p of parts) p.dispose();
  for (const p of list) p.dispose();
  return g;
}

/** A five-petal blossom with a deeper centre, about one unit across, facing +z. */
function flowerGeometry() {
  const petals = [];
  for (let k = 0; k < 5; k++) {
    const p = petalGeometry(3, 1);
    p.scale(0.5, 0.5, 0.5);
    p.translate(0, 0.25, 0);
    p.rotateX(0.42);
    p.rotateZ((k / 5) * TAU + 0.3);
    petals.push(p);
  }
  const centre = new THREE.CircleGeometry(0.075, 6);
  centre.translate(0, 0, 0.02);
  const uv = centre.attributes.uv;
  for (let i = 0; i < uv.count; i++) uv.setXY(i, 0.5, 0);
  petals.push(centre);
  return joinGeometries(petals);
}

function roundedRect(w, h, r) {
  const s = new THREE.Shape();
  const x = -w / 2;
  const y = -h / 2;
  s.moveTo(x + r, y);
  s.lineTo(x + w - r, y);
  s.quadraticCurveTo(x + w, y, x + w, y + r);
  s.lineTo(x + w, y + h - r);
  s.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
  s.lineTo(x + r, y + h);
  s.quadraticCurveTo(x, y + h, x, y + h - r);
  s.lineTo(x, y + r);
  s.quadraticCurveTo(x, y, x + r, y);
  return s;
}

/** A box w × h × d with rounded corners and softened edges, centred on the origin. */
function roundedBox(w, h, d, r, bevel = 0.008) {
  const g = new THREE.ExtrudeGeometry(
    roundedRect(w - 2 * bevel, h - 2 * bevel, Math.max(0.002, r - bevel)),
    {
      depth: d - 2 * bevel,
      bevelEnabled: true,
      bevelThickness: bevel,
      bevelSize: bevel,
      bevelSegments: 2,
      curveSegments: 5,
    },
  );
  g.translate(0, 0, -(d - 2 * bevel) / 2);
  return g;
}

/** A tube along a curve that narrows from r0 to r1. */
function taperedTube(curve, segments, r0, r1, sides = 8, buriedRoot = false) {
  const g = new THREE.TubeGeometry(curve, segments, 1, sides, false);
  const pos = g.attributes.position;
  const centre = new THREE.Vector3();
  const p = new THREE.Vector3();
  const radial = sides + 1;
  for (let i = 0; i <= segments; i++) {
    const u = i / segments;
    curve.getPointAt(u, centre);
    const root = Math.min(1, u / 0.12);
    const r = lerp(r0, r1, u ** 0.8) * (buriedRoot ? root * root * (3 - 2 * root) : 1);
    for (let j = 0; j < radial; j++) {
      const k = i * radial + j;
      const ridge =
        r0 > 0.04
          ? 1 +
            0.16 * Math.sin((j / sides) * TAU * 5 + u * 13) +
            0.09 * Math.cos((j / sides) * TAU * 9 - u * 23) +
            0.07 * Math.sin(u * 47 + j * 3)
          : 1;
      p.fromBufferAttribute(pos, k)
        .sub(centre)
        .multiplyScalar(r * ridge)
        .add(centre);
      pos.setXYZ(k, p.x, p.y, p.z);
    }
  }
  g.computeVertexNormals();
  return g;
}

/** The stone as a polar height field: rings packed toward the rim keep the waterline clean. */
export function stoneGeometry(palette) {
  const { stone } = PLACE;
  const rings = [];
  for (let k = 1; k <= 44; k++) rings.push(Math.sin((k / 44) * (Math.PI / 2)));
  rings.push(1.0, 1.06, 1.16);
  const around = 112;
  const positions = [0, 0, 0];
  const colors = [];
  const uvs = [0, 0];
  const grain = new Noise3(seededRandom(0x5701e));
  const dry = new THREE.Color(palette.stone);
  const wet = dry.clone().multiplyScalar(0.2);
  const pale = dry.clone().lerp(new THREE.Color("#a49a7e"), 0.18);
  const tone = new THREE.Color();
  const shade = (x, y, z) => {
    const mottle = 0.5 + 0.5 * grain.at(x * 6.5, y * 6.5, z * 6.5);
    const wetness = 1 - THREE.MathUtils.smoothstep(y, 0.012, 0.11);
    tone
      .copy(dry)
      .lerp(pale, mottle * 0.7)
      .lerp(wet, wetness);
    tone.multiplyScalar(0.9 + 0.2 * grain.at(x * 19, 3.1, z * 19));
    colors.push(tone.r, tone.g, tone.b);
  };
  const c = Math.cos(stone.yaw);
  const s = Math.sin(stone.yaw);
  const top = stoneHeight(stone.x, stone.z);
  positions[0] = stone.x;
  positions[1] = top;
  positions[2] = stone.z;
  shade(stone.x, top, stone.z);
  for (const r of rings)
    for (let a = 0; a < around; a++) {
      const angle = (a / around) * TAU;
      const outline =
        1 +
        0.07 * Math.sin(angle * 3 + 0.7) +
        0.045 * Math.sin(angle * 5 + 2.1) +
        0.022 * Math.sin(angle * 11);
      const lx = Math.cos(angle) * stone.radiusX * r * outline;
      const lz = Math.sin(angle) * stone.radiusZ * r * outline;
      const x = stone.x + lx * c + lz * s;
      const z = stone.z - lx * s + lz * c;
      const y = Math.max(-0.08, stoneHeight(x, z));
      const edge = THREE.MathUtils.smoothstep(r, 0.65, 1);
      const fracture = grain.at(x * 15, y * 24, z * 15) * 0.075 * edge;
      positions.push(x + Math.cos(angle) * fracture, y, z + Math.sin(angle) * fracture);
      uvs.push(lx * 2.4, lz * 2.4);
      shade(x, y, z);
    }
  const index = [];
  // In the x/z plane, the opposite winding faces -Y and culls the top, exposing the water below it.
  for (let a = 0; a < around; a++) index.push(0, 1 + ((a + 1) % around), 1 + a);
  for (let k = 0; k < rings.length - 1; k++)
    for (let a = 0; a < around; a++) {
      const i0 = 1 + k * around + a;
      const i1 = 1 + k * around + ((a + 1) % around);
      const j0 = i0 + around;
      const j1 = i1 + around;
      index.push(i0, i1, j0, i1, j1, j0);
    }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  g.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
  g.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
  g.setIndex(index);
  g.computeVertexNormals();
  const rock = g.toNonIndexed();
  g.dispose();
  const pos = rock.attributes.position,
    uv = rock.attributes.uv;
  const a = new THREE.Vector3(),
    b = new THREE.Vector3(),
    c0 = new THREE.Vector3();
  for (let i = 0; i < pos.count; i += 3) {
    a.fromBufferAttribute(pos, i);
    b.fromBufferAttribute(pos, i + 1).sub(a);
    c0.fromBufferAttribute(pos, i + 2).sub(a);
    b.cross(c0).normalize();
    const top = Math.abs(b.y) > Math.max(Math.abs(b.x), Math.abs(b.z));
    const side = Math.abs(b.x) > Math.abs(b.z);
    for (let k = i; k < i + 3; k++) {
      const u = top || !side ? pos.getX(k) : pos.getZ(k);
      const v = top ? -pos.getZ(k) : pos.getY(k);
      uv.setXY(k, u * 2.3, v * 2.3);
    }
  }
  return rock;
}

/** Original granite maps: quartz grains, mica pits, fissures and roughness, generated once, never per frame. */
function graniteMaps() {
  const size = 512,
    noise = new Noise3(seededRandom(0x67a917e));
  const heights = new Float32Array(size * size),
    colors = new Uint8Array(size * size * 4);
  const normals = new Uint8Array(size * size * 4),
    roughness = new Uint8Array(size * size * 4);
  // Sample a torus so both ends of each axis meet, even under the normal-map gradients.
  const n = (x, y, frequency, z) => {
    const u = (x / size) * TAU,
      v = (y / size) * TAU,
      f = frequency / TAU;
    return noise.at(
      (3 + Math.cos(v)) * Math.cos(u) * f,
      (3 + Math.cos(v)) * Math.sin(u) * f,
      Math.sin(v) * f + z,
    );
  };
  for (let y = 0; y < size; y++)
    for (let x = 0; x < size; x++) {
      const i = y * size + x,
        k = i * 4;
      const coarse = n(x, y, 8, 3),
        grain = n(x, y, 100, 7),
        fine = n(x, y, 230, 11);
      const crack = Math.pow(Math.max(0, 1 - Math.abs(n(x, y, 11, 19) + coarse * 0.35) * 30), 3);
      const mica = Math.max(0, grain - 0.08) * 1.2,
        quartz = Math.max(0, -grain - 0.12);
      heights[i] = coarse * 0.42 + grain * 0.13 + fine * 0.045 - crack * 0.2;
      const tone = Math.max(
        0.12,
        0.68 + coarse * 0.3 + fine * 0.25 + quartz * 0.85 - mica * 0.9 - crack * 0.28,
      );
      colors[k] = Math.min(255, tone * 255);
      colors[k + 1] = Math.min(255, tone * 242);
      colors[k + 2] = Math.min(255, tone * 221);
      colors[k + 3] = 255;
      const rough = Math.min(255, Math.max(90, 215 + grain * 60 - quartz * 120));
      roughness[k] = roughness[k + 1] = roughness[k + 2] = rough;
      roughness[k + 3] = 255;
    }
  const sample = (x, y) => heights[((y + size) % size) * size + ((x + size) % size)];
  for (let y = 0; y < size; y++)
    for (let x = 0; x < size; x++) {
      const dx = (sample(x - 1, y) - sample(x + 1, y)) * 5.5,
        dy = (sample(x, y - 1) - sample(x, y + 1)) * 5.5;
      const length = Math.hypot(dx, dy, 1),
        k = (y * size + x) * 4;
      normals[k] = ((dx / length) * 0.5 + 0.5) * 255;
      normals[k + 1] = ((dy / length) * 0.5 + 0.5) * 255;
      normals[k + 2] = ((1 / length) * 0.5 + 0.5) * 255;
      normals[k + 3] = 255;
    }
  const texture = (data, color = false) => {
    const t = new THREE.DataTexture(data, size, size);
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.magFilter = THREE.LinearFilter;
    t.minFilter = THREE.LinearMipmapLinearFilter;
    t.generateMipmaps = true;
    t.anisotropy = 4;
    if (color) t.colorSpace = THREE.SRGBColorSpace;
    t.needsUpdate = true;
    return t;
  };
  return {
    map: texture(colors, true),
    normalMap: texture(normals),
    roughnessMap: texture(roughness),
  };
}

/** A line of hills: a strip whose top follows ridged noise, its foot under the water. */
function ridgeGeometry(z, height, frequency, seed) {
  const noise = new Noise3(seededRandom(seed));
  const columns = 200;
  const positions = [];
  const tops = [];
  for (let i = 0; i <= columns; i++) {
    const x = lerp(-110, 110, i / columns);
    let h = 0;
    let amp = 0.55;
    let f = frequency;
    for (let o = 0; o < 4; o++) {
      h += amp * (1 - Math.abs(noise.at(x * f, seed % 17, o * 3.7)));
      amp *= 0.48;
      f *= 2.2;
    }
    const y = height * (h - 0.45) * 1.25;
    positions.push(x, Math.max(0.15, y), z, x, -3, z);
    tops.push(1, 0);
  }
  const index = [];
  for (let i = 0; i < columns; i++) {
    const a = i * 2;
    index.push(a, a + 1, a + 2, a + 2, a + 1, a + 3);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
  g.setAttribute("aTop", new THREE.Float32BufferAttribute(tops, 1));
  g.setIndex(index);
  return g;
}

/* ---------- shaders ---------- */

const PETAL_VERTEX = /* glsl */ `
attribute vec4 aData;
varying vec3 vWorld;
varying vec3 vNormal;
varying vec2 vUv;
varying vec4 vData;
void main() {
  mat4 m = modelMatrix;
#ifdef USE_INSTANCING
  m = modelMatrix * instanceMatrix;
#endif
  vec4 w = m * vec4(position, 1.0);
  vWorld = w.xyz;
  vNormal = normalize(mat3(m) * normal);
  vUv = uv;
  vData = aData;
  gl_Position = projectionMatrix * viewMatrix * w;
}`;

const PETAL_FRAGMENT = /* glsl */ `
uniform vec3 uBase;
uniform vec3 uTip;
uniform vec3 uSunDir;
uniform vec3 uSun;
uniform vec3 uSky;
uniform vec3 uGround;
uniform vec3 uHaze;
uniform vec2 uFog;
varying vec3 vWorld;
varying vec3 vNormal;
varying vec2 vUv;
varying vec4 vData;
void main() {
  vec3 n = normalize(vNormal);
  if (!gl_FrontFacing) n = -n;
  vec3 v = normalize(cameraPosition - vWorld);
  vec3 tone = mix(uBase, uTip, smoothstep(0.02, 0.8, vUv.y));
  tone *= mix(vec3(0.78, 0.50, 0.64), vec3(1.08, 1.0, 1.0), vData.y);
  tone = mix(tone, vec3(1.0, .82, .87), smoothstep(.92, 1., vData.y) * smoothstep(.6,1.,vUv.y) * .35);
  float ndl = dot(n, uSunDir);
  vec3 ambient = mix(uGround, uSky, n.y * 0.5 + 0.5);
  vec3 lit = tone * (ambient * 0.88 + uSun * max(ndl, 0.0) * 0.7);
  // Light comes through a petal when the sun is behind it.
  float behind = pow(max(dot(-v, uSunDir), 0.0), 4.0);
  lit += tone * uSun * (max(-ndl, 0.0) * 0.32 + behind * 0.28);
  lit *= 1.0 - 0.07 * exp(-pow((vUv.x - 0.5) * 12.0, 2.0)) * vUv.y;
  lit *= 1.0 - 0.2 * vData.z - 0.23 * vData.w;
  float f = smoothstep(uFog.x, uFog.y, length(vWorld - cameraPosition));
  gl_FragColor = vec4(mix(lit, uHaze, f), vData.x);
  #include <colorspace_fragment>
}`;

const SKY_VERTEX = /* glsl */ `
varying vec3 vDir;
void main() {
  vDir = position;
  gl_Position = projectionMatrix * viewMatrix * modelMatrix * vec4(position, 1.0);
}`;

const SKY_FRAGMENT = /* glsl */ `
uniform vec3 uZenith;
uniform vec3 uHorizon;
uniform vec3 uGlow;
uniform vec3 uSun;
uniform vec3 uSunDir;
varying vec3 vDir;
void main() {
  vec3 d = normalize(vDir);
  float up = clamp(d.y, 0.0, 1.0);
  vec3 col = mix(uHorizon, uZenith, pow(smoothstep(0.0, 0.6, up), 0.62));
  float s = max(dot(d, uSunDir), 0.0);
  col = mix(col, uGlow, pow(s, 5.0) * 0.6 * (1.0 - smoothstep(0.0, 0.45, up)));
  col += uSun * (pow(s, 48.0) * 0.32 + pow(s, 600.0) * 0.55);
  float disc = smoothstep(0.99955, 0.99974, s);
  col = mix(col, uSun * 1.25 + vec3(0.25), disc);
  float band = exp(-pow((d.y - 0.075) * 30.0, 2.0)) * (0.55 + 0.45 * sin(d.x * 11.0 + d.z * 4.0));
  col = mix(col, uGlow, band * 0.1);
  col = mix(col, uHorizon, smoothstep(0.0, -0.04, d.y));
  gl_FragColor = vec4(col, 1.0);
  #include <colorspace_fragment>
}`;

const HILL_VERTEX = /* glsl */ `
attribute float aTop;
varying float vTop;
varying vec3 vWorld;
void main() {
  vTop = aTop;
  vec4 w = modelMatrix * vec4(position, 1.0);
  vWorld = w.xyz;
  gl_Position = projectionMatrix * viewMatrix * w;
}`;

const HILL_FRAGMENT = /* glsl */ `
uniform vec3 uColor;
uniform vec3 uHaze;
uniform vec3 uSun;
uniform vec3 uSunDir;
uniform float uFar;
varying float vTop;
varying vec3 vWorld;
void main() {
  float mist = 1.0 - smoothstep(0.0, 2.6, vWorld.y);
  vec3 col = mix(uColor, uHaze, clamp(uFar + mist * 0.6, 0.0, 1.0));
  vec3 d = normalize(vWorld - cameraPosition);
  float toward = pow(max(dot(normalize(d.xz), normalize(uSunDir.xz)), 0.0), 10.0);
  col += uSun * smoothstep(0.9, 1.0, vTop) * (0.05 + 0.4 * toward) * (1.0 - uFar);
  gl_FragColor = vec4(col, 1.0);
  #include <colorspace_fragment>
}`;

const WATER_VERTEX = /* glsl */ `
uniform mat4 uMirror;
varying vec4 vMirror;
varying vec3 vWorld;
void main() {
  vec4 w = modelMatrix * vec4(position, 1.0);
  vWorld = w.xyz;
  vMirror = uMirror * w;
  gl_Position = projectionMatrix * viewMatrix * w;
}`;

const WATER_FRAGMENT = /* glsl */ `
#define RIPPLES ${RIPPLES}
uniform sampler2D uReflection;
uniform vec2 uTexel;
uniform vec4 uRipples[RIPPLES];
uniform float uTime;
uniform vec3 uDeep;
uniform vec3 uShallow;
uniform vec3 uHaze;
uniform vec3 uSun;
uniform vec3 uSunDir;
varying vec4 vMirror;
varying vec3 vWorld;
void main() {
  vec2 p = vWorld.xz;
  vec2 slope = vec2(0.0);
  for (int i = 0; i < RIPPLES; i++) {
    vec4 r = uRipples[i];
    float age = uTime - r.z;
    if (age <= 0.0 || age > 3.4) continue;
    vec2 d = p - r.xy;
    float dist = length(d);
    float big = step(1.5, r.w);
    float x = dist - (age * (0.3 + 0.12 * big) + big * 0.95);
    float width = 0.03 + age * 0.035;
    float env = exp(-(x * x) / (width * width)) * (1.0 - age / 3.4) * min(r.w, 1.3) / (1.0 + dist * 2.5);
    slope += (d / max(dist, 1e-4)) * cos(x * 75.0) * env;
  }
  slope *= 0.055;
  slope += vec2(sin(p.x * 1.7 + uTime * 0.35) + sin(p.y * 2.3 - uTime * 0.27),
                cos(p.x * 2.1 - uTime * 0.31) + cos(p.y * 1.3 + uTime * 0.22)) * 0.0012;
  slope.y += sin(p.y * 76.0 + sin(p.x * 35.0 + uTime * .6)) * .003;
  vec3 n = normalize(vec3(-slope.x, 1.0, -slope.y));
  vec3 v = normalize(cameraPosition - vWorld);
  float facing = clamp(dot(n, v), 0.0, 1.0);
  float fresnel = 0.04 + 0.96 * pow(1.0 - facing, 5.0);
  vec4 m = vMirror;
  m.xy += slope * m.w * 0.55;
  // A single bilinear sample keeps the ledge and CRT mirror crisp. Fresnel increases toward the far shore.
  vec2 uv = m.xy / m.w;
  vec3 reflected = texture2D(uReflection, uv).rgb;
  float far = smoothstep(1.5, 16.0, length(vWorld.xz - cameraPosition.xz));
  vec3 body = mix(uShallow, uDeep, far);
  vec3 col = mix(body, reflected, clamp(fresnel * .88 + .12, 0.0, 1.0));
  vec3 h = normalize(uSunDir + v);
  // Small capillary waves broaden the glint vertically, while keeping it narrow across the lake.
  float glint = exp(-pow(h.x / .024, 2.) - pow(h.z / .14, 2.));
  vec2 cell = floor(p * vec2(180., 135.));
  float grain = fract(sin(dot(cell,vec2(127.1,311.7)))*43758.5453);
  float wave = .5 + .5*sin(p.y*170. + sin(p.x*81. + uTime)*3. + uTime*1.7);
  float fleck = smoothstep(.68,.96,grain*.65+wave*.35);
  col += uSun * glint * (.06 + fleck*1.9);
  col = mix(col, uHaze, smoothstep(80.0, 220.0, length(vWorld.xz - cameraPosition.xz)) * 0.22);
  gl_FragColor = vec4(col, 1.0);
  #include <colorspace_fragment>
}`;

const SCREEN_VERTEX = /* glsl */ `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

const SCREEN_FRAGMENT = /* glsl */ `
uniform sampler2D uMap;
uniform float uTime;
uniform float uPower;
uniform sampler2D uBackdrop;
uniform float uIdle;
uniform vec3 uGlass;
varying vec2 vUv;
void main() {
  vec2 c = vUv * 2.0 - 1.0;
  vec2 bent = c * (1.0 + 0.05 * dot(c, c));
  vec2 uv = bent * 0.5 + 0.5;
  float inside = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
  vec3 col = texture2D(uMap, uv).rgb * inside;
  float scan = 0.9 + 0.1 * sin(uv.y * 1150.0 + uTime * 3.0);
  float vignette = smoothstep(1.5, 0.6, length(bent * vec2(0.92, 1.0)));
  col *= scan * vignette * uPower;
  vec3 landscape = texture2D(uBackdrop, vec2(.08 + uv.x*.57, .23 + uv.y*.5)).rgb;
  col += landscape * uIdle * .32 * inside * vignette;
  col += uGlass * (0.05 + 0.12 * smoothstep(0.25, 1.0, vUv.y) * smoothstep(1.0, 0.2, vUv.x));
  gl_FragColor = vec4(col, 1.0);
  #include <colorspace_fragment>
}`;

/* ---------- the mirror under the water ---------- */

/** A camera mirrored through the water plane, drawing into a texture the water samples with ripples. */
class Mirror {
  constructor() {
    this.target = new THREE.WebGLRenderTarget(2, 2, { type: THREE.HalfFloatType, samples: 4 });
    this.texel = new THREE.Vector2(0.5, 0.5);
    this.camera = new THREE.PerspectiveCamera();
    this.matrix = new THREE.Matrix4();
    this.normal = new THREE.Vector3(0, 1, 0);
    this.origin = new THREE.Vector3(0, 0, 0);
    this.plane = new THREE.Plane();
    this.clip = new THREE.Vector4();
    this.q = new THREE.Vector4();
    this.eye = new THREE.Vector3();
    this.view = new THREE.Vector3();
    this.look = new THREE.Vector3();
    this.aim = new THREE.Vector3();
    this.rotation = new THREE.Matrix4();
  }

  setSize(width, height) {
    const w = Math.max(2, Math.round(width));
    const h = Math.max(2, Math.round(height));
    this.target.setSize(w, h);
    this.texel.set(1 / w, 1 / h);
  }

  update(camera) {
    const { normal, origin, eye, view, look, aim, rotation } = this;
    eye.setFromMatrixPosition(camera.matrixWorld);
    rotation.extractRotation(camera.matrixWorld);
    view.subVectors(origin, eye).reflect(normal).negate().add(origin);
    look.set(0, 0, -1).applyMatrix4(rotation).add(eye);
    aim.subVectors(origin, look).reflect(normal).negate().add(origin);
    const c = this.camera;
    c.position.copy(view);
    c.up.set(0, 1, 0).applyMatrix4(rotation).reflect(normal);
    c.lookAt(aim);
    c.near = camera.near;
    c.far = camera.far;
    c.updateMatrixWorld();
    c.projectionMatrix.copy(camera.projectionMatrix);
    this.matrix.set(0.5, 0, 0, 0.5, 0, 0.5, 0, 0.5, 0, 0, 0.5, 0.5, 0, 0, 0, 1);
    this.matrix.multiply(c.projectionMatrix).multiply(c.matrixWorldInverse);
    // An oblique near plane on the water, so nothing under it reaches the reflection.
    this.plane.setFromNormalAndCoplanarPoint(normal, origin).applyMatrix4(c.matrixWorldInverse);
    const clip = this.clip.set(
      this.plane.normal.x,
      this.plane.normal.y,
      this.plane.normal.z,
      this.plane.constant,
    );
    const p = c.projectionMatrix.elements;
    const q = this.q;
    q.x = (Math.sign(clip.x) + p[8]) / p[0];
    q.y = (Math.sign(clip.y) + p[9]) / p[5];
    q.z = -1;
    q.w = (1 + p[10]) / p[14];
    clip.multiplyScalar(2 / clip.dot(q));
    p[2] = clip.x;
    p[6] = clip.y;
    p[10] = clip.z + 1 - 0.002;
    p[14] = clip.w;
    c.projectionMatrixInverse.copy(c.projectionMatrix).invert();
  }

  dispose() {
    this.target.dispose();
  }
}

