/* ---------- the scene ---------- */

export class PetalScene {
  /** A scene on the canvas, or null where WebGL is not available. */
  static create(canvas, options) {
    let renderer;
    try {
      renderer = new THREE.WebGLRenderer({
        canvas,
        antialias: !options.phone,
        alpha: false,
        stencil: false,
        powerPreference: "high-performance",
      });
    } catch {
      return null;
    }
    if (!renderer.getContext()) {
      renderer.dispose();
      return null;
    }
    return new PetalScene(renderer, options);
  }

  constructor(renderer, options) {
    this.renderer = renderer;
    this.options = options;
    this.palette = options.palette;
    this.fonts = options.fonts;
    this.screenCopy = options.screenCopy;
    this.onQuality = options.onQuality;
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.NoToneMapping;
    renderer.info.autoReset = false;
    renderer.shadowMap.enabled = true;
    renderer.shadowMap.type = THREE.PCFShadowMap;
    renderer.shadowMap.autoUpdate = false;
    renderer.setClearColor(new THREE.Color(this.palette.horizon), 1);

    this.time = 0;
    this.acc = 0;
    this.width = 1;
    this.height = 1;
    this.dprCap = options.phone ? 1.5 : 2;
    this.quality = 0;
    this.reflectionScale = 0.5;
    this.pixelScale = 1;
    this.frameMs = 16.7;
    this.cpuMs = 0;
    this.slowFrames = 0;
    this.frames = 0;
    this.running = false;
    this.manual = false;
    this.raf = 0;
    this.last = 0;
    this.shadowAge = 99;
    this.pointerAt = new THREE.Vector2();
    this.pointerTime = 0;
    this.parallax = new THREE.Vector2();
    this.kick = 0;
    this.kickSpeed = 0;
    this.shake = -10;
    this.cheer = -10;
    this.screenState = { kind: "logo" };
    this.screenSince = 0;
    this.screenDrawn = -1;
    this.screenBusy = true;

    const scene = new THREE.Scene();
    this.scene = scene;
    this.camera = new THREE.PerspectiveCamera(40, 1, 0.05, 260);
    this.camera.position.copy(EYE);
    this.camera.lookAt(AT);
    this.mirror = new Mirror();

    this.colors = {
      sky: new THREE.Color(this.palette.sky),
      horizon: new THREE.Color(this.palette.horizon),
      glow: new THREE.Color(this.palette.glow),
      sun: new THREE.Color(this.palette.sun),
      white: new THREE.Color("#fff6ea"),
    };
    this.sunDir = new THREE.Vector3(0, 0.1, -1).normalize();
    this.sunColor = this.colors.sun.clone();
    this.skyNow = this.colors.sky.clone();
    // Light from below is the lake giving back the bright sky near the horizon.
    this.groundColor = new THREE.Color(this.palette.water).lerp(
      new THREE.Color(this.palette.horizon),
      0.3,
    );

    this.buildSky();
    this.buildHills();
    this.buildBackdrop();
    this.buildWater();
    this.buildLights();
    this.buildStone();
    this.buildComputer();
    this.buildBranch();
    this.updateBranch(0, 0);
    this.sim = new PetalSim({
      seed: options.seed,
      count: options.phone ? Math.min(options.petalCount, 280) : options.petalCount,
      wind: options.wind,
      blossoms: this.blossomWorld,
    });
    this.buildPetals(this.sim.capacity);
    this.updateBranch(0, 0);
    this.updateLight(0);
    // Web fonts may land after the first drawing of the screen, and a canvas alone may not ask for them: ask, then
    // draw the screen again.
    if (typeof document !== "undefined" && document.fonts) {
      const faces = [`600 38px ${this.fonts.sans}`, `500 34px ${this.fonts.mono}`].map((font) =>
        document.fonts.load(font).catch(() => []),
      );
      Promise.all(faces).then(() => (this.screenBusy = true));
    }
  }

  /* ----- building ----- */

  buildSky() {
    this.skyUniforms = {
      uZenith: { value: new THREE.Color() },
      uHorizon: { value: new THREE.Color(this.palette.horizon) },
      uGlow: { value: new THREE.Color(this.palette.glow) },
      uSun: { value: new THREE.Color(this.palette.sun) },
      uSunDir: { value: this.sunDir },
    };
    const sky = new THREE.Mesh(
      new THREE.SphereGeometry(180, 48, 24),
      new THREE.ShaderMaterial({
        uniforms: this.skyUniforms,
        vertexShader: SKY_VERTEX,
        fragmentShader: SKY_FRAGMENT,
        side: THREE.BackSide,
        depthWrite: false,
      }),
    );
    sky.renderOrder = -10;
    sky.frustumCulled = false;
    this.sky = sky;
    this.scene.add(sky);
  }

  buildHills() {
    const layers = [
      { z: -78, height: 9.5, frequency: 0.03, seed: 11, far: 0.62, color: this.palette.hills[0] },
      { z: -50, height: 5.2, frequency: 0.055, seed: 23, far: 0.42, color: this.palette.hills[1] },
      { z: -30, height: 1.9, frequency: 0.11, seed: 37, far: 0.24, color: this.palette.hills[2] },
    ];
    this.hills = [];
    this.hillUniforms = [];
    for (const layer of layers) {
      const uniforms = {
        uColor: { value: new THREE.Color(layer.color) },
        uHaze: { value: new THREE.Color(this.palette.horizon) },
        uSun: { value: this.sunColor },
        uSunDir: { value: this.sunDir },
        uFar: { value: layer.far },
      };
      this.hillUniforms.push(uniforms);
      const mesh = new THREE.Mesh(
        ridgeGeometry(layer.z, layer.height, layer.frequency, layer.seed),
        new THREE.ShaderMaterial({
          uniforms,
          vertexShader: HILL_VERTEX,
          fragmentShader: HILL_FRAGMENT,
        }),
      );
      mesh.frustumCulled = false;
      this.hills.push(mesh);
      this.scene.add(mesh);
    }
  }

  buildBackdrop() {
    if (!this.options.backdropUrl) return;
    // The image's far shore is at v=.335. That row lies on y=0, so the physical lake meets it exactly.
    const height = 36,
      width = (height * 16) / 9;
    const material = new THREE.MeshBasicMaterial({
      color: this.options.backdropTint ?? "#ffffff",
      toneMapped: false,
    });
    // Preserve the image's shore and mountain scale while extending its sky beyond the
    // photograph. A portrait preview used to expose the top edge of the finite plane.
    const geometry = new THREE.PlaneGeometry(width * 3, height * 4);
    const uv = geometry.getAttribute("uv");
    for (let i = 0; i < uv.count; i++)
      uv.setXY(i, (uv.getX(i) - 0.5) * 3 + 0.5, (uv.getY(i) - 0.5) * 4 + 0.5);
    material.onBeforeCompile = (shader) => {
      shader.uniforms.uPlateZenith = { value: new THREE.Color("#7f95a6") };
      shader.fragmentShader = "uniform vec3 uPlateZenith;\n" + shader.fragmentShader;
      shader.fragmentShader = shader.fragmentShader.replace(
        "#include <map_fragment>",
        `
        #include <map_fragment>
        #ifdef USE_MAP
          float skyExtension = 1. - exp(-max(0., vMapUv.y - 1.) * 3.);
          diffuseColor.rgb = mix(diffuseColor.rgb, uPlateZenith, skyExtension);
        #endif
      `,
      );
    };
    const plate = new THREE.Mesh(geometry, material);
    plate.position.set(5.5, height * (0.5 - 0.335), -50);
    plate.visible = false;
    plate.name = "Distant sky, mountains and far shore (image plate)";
    this.backdrop = plate;
    this.scene.add(plate);
    new THREE.TextureLoader().load(
      this.options.backdropUrl,
      (texture) => {
        if (this.disposed) {
          texture.dispose();
          return;
        }
        texture.colorSpace = THREE.SRGBColorSpace;
        texture.anisotropy = Math.min(4, this.renderer.capabilities.getMaxAnisotropy());
        material.map = texture;
        if (this.screenUniforms) this.screenUniforms.uBackdrop.value = texture;
        material.needsUpdate = true;
        plate.visible = true;
        this.hills.forEach((hill) => (hill.visible = false));
        this.render();
      },
      undefined,
      () => {
        /* The procedural sky and hills stay as an offline fallback. */
      },
    );
  }

  buildWater() {
    this.ripples = Array.from({ length: RIPPLES }, () => new THREE.Vector4(0, 0, -100, 0));
    this.rippleNext = 0;
    const deep = new THREE.Color(this.palette.water);
    this.waterUniforms = {
      uReflection: { value: this.mirror.target.texture },
      uTexel: { value: this.mirror.texel },
      uMirror: { value: this.mirror.matrix },
      uRipples: { value: this.ripples },
      uTime: { value: 0 },
      uDeep: { value: deep },
      uShallow: {
        value: deep.clone().multiplyScalar(0.65),
      },
      uHaze: { value: new THREE.Color(this.palette.horizon) },
      uSun: { value: this.sunColor },
      uSunDir: { value: this.sunDir },
    };
    const water = new THREE.Mesh(
      new THREE.PlaneGeometry(320, 320, 1, 1),
      new THREE.ShaderMaterial({
        uniforms: this.waterUniforms,
        vertexShader: WATER_VERTEX,
        fragmentShader: WATER_FRAGMENT,
      }),
    );
    water.rotation.x = -Math.PI / 2;
    water.position.set(0, 0, -80);
    water.frustumCulled = false;
    this.water = water;
    this.scene.add(water);
  }

  buildLights() {
    this.sunLight = new THREE.DirectionalLight(this.sunColor, 2.4);
    this.sunLight.castShadow = true;
    const shadow = this.sunLight.shadow;
    const size = this.options.phone ? 1024 : 2048;
    shadow.mapSize.set(size, size);
    shadow.camera.left = -2.4;
    shadow.camera.right = 2.4;
    shadow.camera.top = 2.4;
    shadow.camera.bottom = -2.4;
    shadow.camera.near = 0.5;
    shadow.camera.far = 14;
    shadow.bias = -0.0006;
    shadow.normalBias = 0.012;
    shadow.radius = 3;
    this.sunLight.target.position.set(PLACE.computer.x, 0.3, PLACE.computer.z);
    this.scene.add(this.sunLight, this.sunLight.target);
    this.hemi = new THREE.HemisphereLight(
      new THREE.Color(this.palette.sky),
      this.groundColor,
      1.25,
    );
    this.scene.add(this.hemi);
    const fill = new THREE.DirectionalLight("#dce8f5", 0.9);
    fill.position.set(-2, 3, 5);
    this.scene.add(fill);
  }

  buildStone() {
    const stone = new THREE.Mesh(
      stoneGeometry(this.palette),
      new THREE.MeshStandardMaterial({
        ...graniteMaps(),
        vertexColors: true,
        roughness: 1,
        normalScale: new THREE.Vector2(0.9, 0.9),
        metalness: 0,
      }),
    );
    stone.material.onBeforeCompile = (shader) => {
      shader.vertexShader = "varying vec3 vRock;\n" + shader.vertexShader;
      shader.vertexShader = shader.vertexShader.replace(
        "#include <begin_vertex>",
        "#include <begin_vertex>\nvRock = position;",
      );
      shader.fragmentShader =
        `varying vec3 vRock;
        float rockHash(vec3 p){return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453);}
        float rockNoise(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);
          return mix(mix(mix(rockHash(i),rockHash(i+vec3(1,0,0)),f.x),mix(rockHash(i+vec3(0,1,0)),rockHash(i+vec3(1,1,0)),f.x),f.y),mix(mix(rockHash(i+vec3(0,0,1)),rockHash(i+vec3(1,0,1)),f.x),mix(rockHash(i+vec3(0,1,1)),rockHash(i+vec3(1,1,1)),f.x),f.y),f.z);}
        vec3 growthGradient(vec3 p) {
          vec3 h=fract(p*vec3(.1031,.103,.0973));
          h+=dot(h,h.yxz+33.33);
          return normalize(fract((h.xxy+h.yzz)*h.zyx)*2.-1.);
        }
        float growthNoise(vec3 p) {
          vec3 i=floor(p), f=fract(p), u=f*f*f*(f*(f*6.-15.)+10.);
          return mix(mix(mix(dot(growthGradient(i),f),dot(growthGradient(i+vec3(1,0,0)),f-vec3(1,0,0)),u.x),
            mix(dot(growthGradient(i+vec3(0,1,0)),f-vec3(0,1,0)),dot(growthGradient(i+vec3(1,1,0)),f-vec3(1,1,0)),u.x),u.y),
            mix(mix(dot(growthGradient(i+vec3(0,0,1)),f-vec3(0,0,1)),dot(growthGradient(i+vec3(1,0,1)),f-vec3(1,0,1)),u.x),
            mix(dot(growthGradient(i+vec3(0,1,1)),f-vec3(0,1,1)),dot(growthGradient(i+vec3(1,1,1)),f-vec3(1,1,1)),u.x),u.y),u.z);
        }
        // World-space growth masks share the granite's surface, albedo and roughness.
        // Several scales and a soft edge retain mineral detail instead of forming flat pale islands.
        vec2 rockGrowth(vec3 p) {
          float coarse=growthNoise(p*7.);
          float fine=growthNoise(p*43.+vec3(9,3,7));
          float mossField=coarse*.7 + growthNoise(p*17.)*.3 + fine*.12;
          float lichenField=growthNoise(p*26.+coarse*.6)*.7 + fine*.3;
          float dry=smoothstep(.1,.27,p.y);
          return vec2(smoothstep(-.05,.3,mossField)*dry,
            smoothstep(.02,.34,lichenField)*dry*(.5+.5*smoothstep(-.2,.2,coarse)));
        }
      ` + shader.fragmentShader;
      shader.fragmentShader = shader.fragmentShader.replace(
        "#include <color_fragment>",
        `#include <color_fragment>
        float seam=rockNoise(vRock*12. + rockNoise(vRock*4.)*3.);
        float mineral=rockNoise(vRock*230.);
        diffuseColor.rgb *= .7+seam*.7+mineral*.3;
        float vein=pow(abs(sin(vRock.y*68. + rockNoise(vRock*9.)*6.)),22.);
        diffuseColor.rgb *= 1.-vein*.45;
        vec2 growth=rockGrowth(vRock);
        diffuseColor.rgb=mix(diffuseColor.rgb,
          diffuseColor.rgb*vec3(.55,.78,.34)+vec3(.003,.005,.001),growth.x*.72);
        diffuseColor.rgb*=mix(vec3(1.),vec3(1.24,1.31,.91),growth.y*.65);
      `,
      );
      shader.fragmentShader = shader.fragmentShader.replace(
        "#include <normal_fragment_begin>",
        `#include <normal_fragment_begin>
        float rockHeight=rockNoise(vRock*38.)*.012+rockNoise(vRock*190.)*.003;
        vec3 sx=dFdx(-vViewPosition),sy=dFdy(-vViewPosition);
        vec3 r1=cross(sy,normal),r2=cross(normal,sx);
        float det=dot(sx,r1);
        normal=normalize(abs(det)*normal-sign(det)*(dFdx(rockHeight)*r1+dFdy(rockHeight)*r2));
      `,
      );
    };
    const compileRock = stone.material.onBeforeCompile;
    stone.material.onBeforeCompile = (shader) => {
      compileRock(shader);
      shader.fragmentShader = shader.fragmentShader.replace(
        "#include <roughnessmap_fragment>",
        `#include <roughnessmap_fragment>
        roughnessFactor=mix(roughnessFactor,.98,growth.x*.65);
        roughnessFactor=mix(roughnessFactor,.9,growth.y*.45);
        roughnessFactor*=mix(.36,1.,smoothstep(.02,.12,vRock.y));`,
      );
    };
    this.stone = stone;
    stone.name = "Granite ledge above the waterline";
    stone.receiveShadow = true;
    stone.castShadow = true;
    this.scene.add(stone);
  }

  buildComputer() {
    const p = this.palette;
    const group = new THREE.Group();
    group.position.set(PLACE.computer.x, PARTS.base, PLACE.computer.z);
    group.rotation.y = PLACE.computer.yaw;
    const computerScale = PLACE.computer.scale;
    group.scale.setScalar(computerScale);
    const body = new THREE.MeshStandardMaterial({
      color: p.computer,
      roughness: 0.48,
      metalness: 0,
    });
    const trim = new THREE.MeshStandardMaterial({ color: p.keys, roughness: 0.6, metalness: 0 });
    const dark = new THREE.MeshStandardMaterial({
      color: "#1d2123",
      roughness: 0.55,
      metalness: 0,
    });
    const add = (geometry, material, x, y, z, cast = true) => {
      const m = new THREE.Mesh(geometry, material);
      m.position.set(x, y, z);
      m.castShadow = cast;
      m.receiveShadow = true;
      group.add(m);
      return m;
    };
    const base = PARTS.base;
    // The system unit, with two drive slots and a groove.
    add(roundedBox(0.58, 0.1, 0.5, 0.02, 0.01), body, 0, 0.05, 0);
    add(new THREE.BoxGeometry(0.15, 0.011, 0.01), dark, -0.13, 0.058, 0.25);
    add(new THREE.BoxGeometry(0.15, 0.011, 0.01), dark, 0.07, 0.058, 0.25);
    add(new THREE.BoxGeometry(0.03, 0.006, 0.006), trim, 0.21, 0.058, 0.252);
    add(new THREE.BoxGeometry(0.56, 0.004, 0.004), trim, 0, 0.022, 0.251, false);
    // The monitor and the tube's back.
    const monitorTop = (PARTS.monitor.top - base) / computerScale;
    const monitorH = 0.43;
    const monitorY = monitorTop - monitorH / 2;
    add(roundedBox(0.51, monitorH, 0.455, 0.045, 0.014), body, 0, monitorY, -0.0225);
    add(roundedBox(0.36, 0.34, 0.24, 0.06, 0.02), body, 0, monitorY - 0.02, -0.33);
    for (let k = 0; k < 6; k++)
      add(
        new THREE.BoxGeometry(0.2, 0.004, 0.012),
        dark,
        0,
        monitorTop - 0.001,
        -0.21 + k * 0.026,
        false,
      );
    // The dark glass around the picture, and the picture itself.
    const front = 0.205;
    const faceY = monitorY + 0.025;
    add(roundedBox(0.43, 0.33, 0.012, 0.035, 0.004), dark, 0, faceY, front);
    const screenGeometry = new THREE.PlaneGeometry(0.38, 0.285, 18, 14);
    const sp = screenGeometry.attributes.position;
    for (let i = 0; i < sp.count; i++) {
      const x = sp.getX(i) / 0.19;
      const y = sp.getY(i) / 0.1425;
      sp.setZ(i, 0.011 * (1 - x * x * 0.8) * (1 - y * y * 0.8));
    }
    screenGeometry.computeVertexNormals();
    this.screenCanvas = typeof document !== "undefined" ? document.createElement("canvas") : null;
    if (this.screenCanvas) {
      this.screenCanvas.width = SCREEN_SIZE.width;
      this.screenCanvas.height = SCREEN_SIZE.height;
    }
    this.screenContext = this.screenCanvas?.getContext("2d") ?? null;
    this.screenTexture = new THREE.CanvasTexture(this.screenCanvas ?? undefined);
    this.screenTexture.colorSpace = THREE.SRGBColorSpace;
    this.screenTexture.generateMipmaps = false;
    this.screenTexture.minFilter = THREE.LinearFilter;
    this.screenTexture.anisotropy = 4;
    this.screenUniforms = {
      uMap: { value: this.screenTexture },
      uBackdrop: { value: this.screenTexture },
      uIdle: { value: 0 },
      uTime: { value: 0 },
      uPower: { value: 1.15 },
      uGlass: { value: new THREE.Color(p.sky).multiplyScalar(0.6) },
    };
    const screen = new THREE.Mesh(
      screenGeometry,
      new THREE.ShaderMaterial({
        uniforms: this.screenUniforms,
        vertexShader: SCREEN_VERTEX,
        fragmentShader: SCREEN_FRAGMENT,
      }),
    );
    screen.position.set(0, faceY, front + 0.0075);
    group.add(screen);
    // The badge: our mark, small, under the picture; and the power light.
    const badgeCanvas = typeof document !== "undefined" ? document.createElement("canvas") : null;
    if (badgeCanvas) {
      badgeCanvas.width = 64;
      badgeCanvas.height = 64;
      const ctx = badgeCanvas.getContext("2d");
      if (ctx) drawMark(ctx, 32, 30, 15, "#7d7a72", "#7d7a72", 0.7);
    }
    this.badgeTexture = new THREE.CanvasTexture(badgeCanvas ?? undefined);
    this.badgeTexture.colorSpace = THREE.SRGBColorSpace;
    const badge = new THREE.Mesh(
      new THREE.PlaneGeometry(0.034, 0.034),
      new THREE.MeshStandardMaterial({ map: this.badgeTexture, transparent: true, roughness: 0.5 }),
    );
    badge.position.set(-0.17, faceY - 0.182, front + 0.0005);
    group.add(badge);
    this.led = new THREE.Mesh(
      new THREE.BoxGeometry(0.012, 0.006, 0.004),
      new THREE.MeshBasicMaterial({ color: "#8fe3a6" }),
    );
    this.led.position.set(0.185, faceY - 0.183, front + 0.002);
    group.add(this.led);
    // Screen light on the keyboard and the stone.
    this.screenLight = new THREE.PointLight(new THREE.Color(p.screenAccent), 0.5, 1.6, 2);
    this.screenLight.position.set(0, faceY, front + 0.18);
    group.add(this.screenLight);

    // The keyboard, a little lower on the stone, with its own keys.
    const keyboard = new THREE.Group();
    keyboard.position.set(0, (PARTS.keyboardBase - base) / computerScale, 0.42);
    keyboard.rotation.x = 0.06;
    group.add(keyboard);
    const deck = new THREE.Mesh(roundedBox(0.47, 0.022, 0.16, 0.012, 0.006), body);
    deck.position.y = 0.011;
    deck.castShadow = true;
    deck.receiveShadow = true;
    keyboard.add(deck);
    this.keys = [];
    const pitch = 0.031;
    KEY_ROWS.forEach((row, r) => {
      for (let k = 0; k < row.length; k++)
        this.keys.push({
          char: row[k],
          x: -0.2 + k * pitch + r * 0.008,
          z: -0.054 + r * 0.03,
          w: 1,
          at: -10,
        });
    });
    this.keys.push({ char: " ", x: 0.0, z: 0.066, w: 6.2, at: -10 });
    this.keys.push({ char: "Backspace", x: 0.19, z: -0.054, w: 1.7, at: -10 });
    this.keys.push({ char: "Enter", x: 0.19, z: 0.006, w: 1.7, at: -10 });
    const keyMaterial = new THREE.MeshStandardMaterial({ color: "#ffffff", roughness: 0.55 });
    this.keyMesh = new THREE.InstancedMesh(
      new THREE.BoxGeometry(0.026, 0.012, 0.026),
      keyMaterial,
      this.keys.length,
    );
    this.keyMesh.castShadow = true;
    this.keyMesh.receiveShadow = true;
    const keyColor = new THREE.Color(p.keys);
    const accentKey = new THREE.Color(p.petalDeep).lerp(new THREE.Color(p.keys), 0.35);
    this.keys.forEach((key, i) =>
      this.keyMesh.setColorAt(i, key.char === "Enter" ? accentKey : keyColor),
    );
    this.keyMatrix = new THREE.Matrix4();
    this.keys.forEach((_, i) => this.placeKey(i, 0));
    keyboard.add(this.keyMesh);
    // The cable from the keyboard back to the unit, lying on the stone.
    const cable = new THREE.CatmullRomCurve3([
      new THREE.Vector3(-0.2, (PARTS.keyboardBase - base) / computerScale + 0.012, 0.34),
      new THREE.Vector3(-0.27, 0.006, 0.33),
      new THREE.Vector3(-0.34, 0.005, 0.27),
      new THREE.Vector3(-0.33, 0.006, 0.2),
      new THREE.Vector3(-0.29, 0.03, 0.16),
    ]);
    add(new THREE.TubeGeometry(cable, 32, 0.0055, 6, false), dark, 0, 0, 0);
    this.computer = group;
    this.scene.add(group);
  }

  placeKey(i, press) {
    const key = this.keys[i];
    this.keyMatrix.makeScale(key.w, 1, 1);
    this.keyMatrix.setPosition(key.x, 0.028 - press * 0.006, key.z);
    this.keyMesh.setMatrixAt(i, this.keyMatrix);
  }

  buildBranch() {
    const p = this.palette,
      random = seededRandom(0xb1055);
    const group = new THREE.Group();
    const anchor = new THREE.Vector3(1.52, 0.27, -0.38);
    group.position.copy(anchor);
    const local = (x, y, z) => new THREE.Vector3(x, y - 0.13, z).sub(anchor);
    const curve = (points) => new THREE.CatmullRomCurve3(points.map((p) => local(...p)));
    const trunk = curve([
      [1.85, 0.37, -0.38],
      [1.85, 0.72, -0.4],
      [1.58, 1.12, -0.32],
      [1.12, 1.6, -0.18],
      [1.02, 2.04, -0.28],
    ]);
    const limbs = [
      curve([
        [1.43, 1.12, -0.32],
        [1.14, 1.42, -0.15],
        [0.66, 1.57, 0.05],
        [0.1, 1.61, 0.12],
        [-0.56, 1.52, 0.16],
        [-1.05, 1.7, 0.04],
      ]),
      curve([
        [1.12, 1.6, -0.18],
        [0.72, 1.78, -0.26],
        [0.1, 1.93, -0.22],
        [-0.48, 1.84, -0.1],
        [-0.91, 2.02, 0.05],
      ]),
      curve([
        [1.43, 1.12, -0.32],
        [1.69, 1.43, -0.25],
        [1.96, 1.68, -0.1],
        [2.22, 1.96, -0.2],
      ]),
      curve([
        [1.14, 1.42, -0.15],
        [1.16, 1.57, 0.3],
        [0.81, 1.75, 0.48],
        [0.25, 1.78, 0.45],
        [-0.35, 1.8, 0.52],
      ]),
      curve([
        [1.12, 1.6, -0.18],
        [1.45, 1.85, -0.6],
        [1.7, 2.07, -0.8],
      ]),
    ];
    const bark = createBarkMaterial({
      path: this.options.barkTexturePath,
      tint: p.bark,
      isDisposed: () => this.disposed,
      onLoad: () => {
        if (!this.running || this.manual) this.render();
      },
    });
    const wood = [taperedTube(trunk, 100, 0.26, 0.065, 24)];
    limbs.forEach((c, i) => wood.push(taperedTube(c, 44, i === 0 ? 0.115 : 0.073, 0.005, 8, true)));
    for (let i = 0; i < 6; i++) {
      const a = i * 1.05;
      const x = 1.85 + Math.cos(a) * 0.43,
        z = -0.38 + Math.sin(a) * 0.38;
      wood.push(
        taperedTube(
          curve([
            [1.85, 0.48, -0.38],
            [1.85 + Math.cos(a) * 0.2, 0.43, -0.38 + Math.sin(a) * 0.2],
            [x, Math.max(0.025, stoneHeight(x, z)) + 0.136, z],
          ]),
          16,
          0.09,
          0.006,
          7,
        ),
      );
    }
    const flowers = [];
    for (const limb of limbs)
      for (let i = 1; i <= 24; i++) {
        const t = 0.15 + (i / 24) * 0.8,
          at = limb.getPointAt(t);
        const side = i % 2 ? 1 : -1;
        const tip = at
          .clone()
          .add(
            new THREE.Vector3(
              -0.12 - random() * 0.18,
              (random() - 0.35) * 0.32,
              side * (0.16 + random() * 0.36),
            ),
          );
        const twig = new THREE.CatmullRomCurve3([
          at,
          at
            .clone()
            .lerp(tip, 0.5)
            .add(new THREE.Vector3(0, 0.04, 0)),
          tip,
        ]);
        wood.push(taperedTube(twig, 10, 0.008, 0.0015, 5));
        for (let c = 0; c < 7; c++) {
          const spot = twig.getPointAt(0.16 + c * 0.13);
          for (let k = 0; k < (this.options.phone ? 6 : 8); k++) {
            const offset = new THREE.Vector3(
              (random() - 0.5) * 0.21,
              (random() - 0.45) * 0.18,
              (random() - 0.5) * 0.18,
            );
            const facing = new THREE.Vector3(
              (random() - 0.5) * 1.8,
              (random() - 0.4) * 1.7,
              0.3 + random(),
            ).normalize();
            flowers.push({
              at: spot.clone().add(offset),
              facing,
              size: 0.055 + random() * 0.04,
              tint: random(),
            });
          }
        }
      }
    const woodMesh = new THREE.Mesh(joinGeometries(wood), bark);
    woodMesh.castShadow = true;
    woodMesh.receiveShadow = true;
    group.add(woodMesh);
    const flowerData = new Float32Array(flowers.length * 4),
      flowerGeom = flowerGeometry();
    flowerGeom.setAttribute("aData", new THREE.InstancedBufferAttribute(flowerData, 4));
    this.flowerUniforms = this.petalUniforms(p.petalDeep, p.blossom);
    const mesh = new THREE.InstancedMesh(
      flowerGeom,
      new THREE.ShaderMaterial({
        uniforms: this.flowerUniforms,
        vertexShader: PETAL_VERTEX,
        fragmentShader: PETAL_FRAGMENT,
        side: THREE.DoubleSide,
      }),
      flowers.length,
    );
    const matrix = new THREE.Matrix4(),
      q = new THREE.Quaternion(),
      zAxis = new THREE.Vector3(0, 0, 1);
    flowers.forEach((f, i) => {
      q.setFromUnitVectors(zAxis, f.facing);
      matrix.compose(f.at, q, new THREE.Vector3(f.size, f.size, f.size));
      mesh.setMatrixAt(i, matrix);
      flowerData[i * 4] = 1;
      flowerData[i * 4 + 1] = f.tint;
      flowerData[i * 4 + 3] = random() * 0.65;
    });
    mesh.name = `Full bloom — ${flowers.length.toLocaleString()} instanced cherry blossoms`;
    group.add(mesh);
    this.blossomLocal = flowers.map((f) => f.at);
    this.blossomWorld = new Float32Array(flowers.length * 3);
    this.branch = group;
    this.scene.add(group);
  }

  petalUniforms(base, tip) {
    return {
      uBase: { value: new THREE.Color(base) },
      uTip: { value: new THREE.Color(tip) },
      uSunDir: { value: this.sunDir },
      uSun: { value: this.sunColor },
      uSky: { value: this.skyNow },
      uGround: { value: this.groundColor },
      uHaze: { value: new THREE.Color(this.palette.horizon) },
      uFog: { value: new THREE.Vector2(9, 60) },
    };
  }

  buildPetals(capacity) {
    const geometry = petalGeometry();
    this.petalData = new THREE.InstancedBufferAttribute(new Float32Array(capacity * 4), 4);
    this.petalData.setUsage(THREE.DynamicDrawUsage);
    geometry.setAttribute("aData", this.petalData);
    this.petalUniformValues = this.petalUniforms(this.palette.petalDeep, this.palette.petal);
    this.petals = new THREE.InstancedMesh(
      geometry,
      new THREE.ShaderMaterial({
        uniforms: this.petalUniformValues,
        vertexShader: PETAL_VERTEX,
        fragmentShader: PETAL_FRAGMENT,
        side: THREE.DoubleSide,
        transparent: true,
        depthWrite: false,
      }),
      capacity,
    );
    this.petals.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this.petals.frustumCulled = false;
    this.petals.count = 0;
    this.order = new Uint16Array(capacity);
    this.depth = new Float32Array(capacity);
    this.tmp = {
      m: new THREE.Matrix4(),
      q: new THREE.Quaternion(),
      e: new THREE.Euler(),
      p: new THREE.Vector3(),
      s: new THREE.Vector3(),
      v: new THREE.Vector3(),
      vp: new THREE.Matrix4(),
      right: new THREE.Vector3(),
      up: new THREE.Vector3(),
    };
    this.scene.add(this.petals);
  }

  /* ----- per frame ----- */

  updateLight(t) {
    const c = 0.08 + Math.sin(t * 0.04) * 0.015;
    // Match the sun in the plate, just left of the snow range. Light does not orbit a static image.
    this.sunDir.set(-0.2, 0.24, -1).normalize();
    this.sunColor.copy(this.colors.sun).lerp(this.colors.white, c * 0.55);
    this.skyNow.copy(this.colors.sky).lerp(this.colors.white, c * 0.08);
    this.skyUniforms.uZenith.value.copy(this.skyNow);
    this.skyUniforms.uSun.value.copy(this.sunColor);
    this.skyUniforms.uGlow.value.copy(this.colors.glow).lerp(this.colors.horizon, c * 0.35);
    this.sunLight.color.copy(this.sunColor);
    this.sunLight.intensity = 2.6;
    this.sunLight.position.copy(this.sunLight.target.position).addScaledVector(this.sunDir, 7);
    this.hemi.color.copy(this.skyNow);
  }

  updateCamera(dt, t) {
    const k = 1 - Math.exp(-dt * 2.5);
    this.parallax.x += (this.pointerAt.x - this.parallax.x) * k;
    this.parallax.y += (this.pointerAt.y - this.parallax.y) * k;
    const cam = this.camera;
    cam.position.set(
      EYE.x + Math.sin(t * 0.071) * 0.05 + this.parallax.x * 0.09,
      EYE.y + Math.sin(t * 0.053) * 0.014 + this.parallax.y * 0.03,
      EYE.z,
    );
    cam.lookAt(AT.x + this.parallax.x * 0.03, AT.y, AT.z);
    cam.updateMatrixWorld();
    this.sky.position.copy(cam.position);
  }

  updateBranch(dt, t) {
    // A spring: keystrokes and the success gust push it, and it settles back.
    this.kickSpeed += (-this.kick * 38 - this.kickSpeed * 5.5) * dt;
    this.kick += this.kickSpeed * dt;
    const gust = this.sim ? this.sim.gust : 0;
    const b = this.branch;
    b.rotation.z =
      0.003 * Math.sin(t * 0.8) +
      0.002 * Math.sin(t * 1.9 + 1) +
      this.kick * 0.25 +
      gust * 0.008 * Math.sin(t * 6.5);
    b.rotation.x = 0.002 * Math.sin(t * 0.6 + 0.4) + this.kick * 0.1;
    b.updateMatrixWorld(true);
    const v = SCRATCH;
    this.blossomLocal.forEach((p, i) => {
      v.copy(p).applyMatrix4(b.matrixWorld);
      this.blossomWorld[i * 3] = v.x;
      this.blossomWorld[i * 3 + 1] = v.y;
      this.blossomWorld[i * 3 + 2] = v.z;
    });
    if (this.sim) this.sim.setBlossoms(this.blossomWorld);
  }

  updateKeys(t) {
    let moved = false;
    this.keys.forEach((key, i) => {
      const age = t - key.at;
      if (age < 0 || age > 0.3) {
        if (key.down) {
          key.down = false;
          this.placeKey(i, 0);
          moved = true;
        }
        return;
      }
      key.down = true;
      const press = age < 0.05 ? age / 0.05 : Math.max(0, 1 - (age - 0.05) / 0.22);
      this.placeKey(i, press);
      moved = true;
    });
    if (moved) this.keyMesh.instanceMatrix.needsUpdate = true;
  }

  updateScreen(t) {
    const since = t - this.screenSince;
    const s = this.screenState;
    const shaking = t - this.shake < 0.5;
    this.screenUniforms.uTime.value = t;
    this.screenUniforms.uIdle.value = s.kind === "logo" && this.backdrop?.visible ? 1 : 0;
    this.screenUniforms.uPower.value =
      (s.kind === "welcome" ? 1.25 : 1.12) * (shaking ? 0.85 + 0.15 * Math.sin(t * 90) : 1);
    const ledColors = {
      pending: Math.sin(t * 9) > 0 ? "#ffcf7a" : "#6b5a3a",
      error: "#ff7b66",
      welcome: "#fff4dc",
    };
    this.led.material.color.set(ledColors[s.kind] ?? "#8fe3a6");
    const cheer = Math.max(0, 1 - (t - this.cheer) / 2.5);
    this.screenLight.intensity = 0.45 + (s.kind === "welcome" ? 0.35 : 0) + cheer * 0.6;
    this.screenLight.color.set(
      s.kind === "error" ? this.palette.screenError : this.palette.screenAccent,
    );
    if (!this.screenContext) return;
    // Redraw at once after a change, then about 30 times a second while something on it moves.
    const frame = Math.floor(t * 30);
    if (!this.screenBusy && (frame === this.screenDrawn || !screenMoves(s, since))) return;
    this.screenDrawn = frame;
    this.screenBusy = false;
    drawScreen(
      this.screenContext,
      s,
      since,
      t,
      this.screenCopy,
      {
        background: this.palette.screen,
        text: this.palette.screenText,
        dim: this.palette.screenDim,
        accent: this.palette.screenAccent,
        error: this.palette.screenError,
      },
      this.fonts,
    );
    this.screenTexture.needsUpdate = true;
  }

  updatePetals() {
    const sim = this.sim;
    const { m, q, e, p, s } = this.tmp;
    const eye = this.camera.position;
    const order = this.order;
    const depth = this.depth;
    let count = 0;
    for (let i = 0; i < sim.capacity; i++) {
      if (sim.mode[i] === PETAL_MODES.IDLE || sim.alpha[i] <= 0.004) continue;
      const dx = sim.x[i] - eye.x;
      const dy = sim.y[i] - eye.y;
      const dz = sim.z[i] - eye.z;
      depth[i] = dx * dx + dy * dy + dz * dz;
      order[count++] = i;
    }
    const sorted = order.subarray(0, count).sort((a, b) => depth[b] - depth[a]);
    const matrices = this.petals.instanceMatrix.array;
    const data = this.petalData.array;
    for (let k = 0; k < count; k++) {
      const i = sorted[k];
      e.set(sim.rx[i], sim.ry[i], sim.rz[i]);
      q.setFromEuler(e);
      p.set(sim.x[i], sim.y[i], sim.z[i]);
      const size = sim.size[i] * PETAL_LENGTH;
      s.set(size, size, size);
      m.compose(p, q, s);
      m.toArray(matrices, k * 16);
      data[k * 4] = sim.alpha[i];
      data[k * 4 + 1] = sim.tint[i];
      data[k * 4 + 2] = sim.wet[i];
      data[k * 4 + 3] = 0;
    }
    this.petals.count = count;
    this.petals.instanceMatrix.needsUpdate = true;
    this.petalData.needsUpdate = true;
  }

  ripple(x, z, strength) {
    this.ripples[this.rippleNext].set(x, z, this.time, strength);
    this.rippleNext = (this.rippleNext + 1) % RIPPLES;
  }

  /* ----- the frame ----- */

  frame(dt) {
    const started = performance.now();
    const renderer = this.renderer;
    renderer.info.reset();
    this.acc += dt;
    let steps = 0;
    while (this.acc >= PETAL_STEP - 1e-6 && steps < 5) {
      this.sim.step(PETAL_STEP);
      this.acc -= PETAL_STEP;
      steps++;
    }
    if (steps === 5) this.acc = 0;
    this.time += dt;
    const t = this.time;
    this.sim.drainLandings((x, z, strength) => this.ripple(x, z, strength));
    this.updateLight(t);
    this.updateCamera(dt, t);
    this.updateBranch(dt, t);
    this.updateKeys(t);
    this.updateScreen(t);
    this.updatePetals();
    this.waterUniforms.uTime.value = t;

    if (++this.shadowAge > 12) {
      renderer.shadowMap.needsUpdate = true;
      this.shadowAge = 0;
    }
    this.mirror.update(this.camera);
    this.water.visible = false;
    renderer.setRenderTarget(this.mirror.target);
    renderer.clear();
    renderer.render(this.scene, this.mirror.camera);
    renderer.setRenderTarget(null);
    this.water.visible = true;
    renderer.render(this.scene, this.camera);
    this.cpuMs = lerp(this.cpuMs, performance.now() - started, 0.1);
  }

  loop = (now) => {
    this.raf = requestAnimationFrame(this.loop);
    const gap = this.last ? now - this.last : 16.7;
    this.last = now;
    this.frame(Math.min(gap, 100) / 1000);
    this.adapt(gap);
  };

  /** Steps quality down while frames keep running long: reflection first, then petals, then pixels. */
  adapt(gap) {
    if (this.manual) return;
    this.frames++;
    this.frameMs = lerp(this.frameMs, gap, 0.08);
    if (this.frames < 45 || gap > 250) return;
    this.slowFrames = this.frameMs > 24 ? this.slowFrames + 1 : Math.max(0, this.slowFrames - 2);
    if (this.slowFrames < 50 || this.quality >= 3) return;
    this.slowFrames = 0;
    this.frames = 0;
    this.quality++;
    if (this.quality === 1) this.reflectionScale = 0.25;
    if (this.quality === 2) this.sim.density = 0.5;
    if (this.quality === 3) this.pixelScale = 0.75;
    this.setSize(this.width, this.height);
    this.onQuality?.(this.qualityState());
  }

  qualityState() {
    return {
      level: this.quality,
      reflectionScale: this.reflectionScale,
      density: this.sim.density,
      pixelRatio: this.renderer.getPixelRatio(),
    };
  }

  /* ----- what the component calls ----- */

  setSize(width, height) {
    this.width = Math.max(1, width);
    this.height = Math.max(1, height);
    const ratio =
      Math.min(typeof devicePixelRatio === "number" ? devicePixelRatio : 1, this.dprCap) *
      this.pixelScale;
    this.renderer.setPixelRatio(ratio);
    this.renderer.setSize(this.width, this.height, false);
    const aspect = this.width / this.height;
    this.camera.aspect = aspect;
    this.camera.fov =
      aspect < 1 ? (2 * Math.atan(Math.tan((20 * Math.PI) / 180) / aspect) * 180) / Math.PI : 40;
    this.camera.updateProjectionMatrix();
    this.mirror.setSize(
      this.width * ratio * this.reflectionScale,
      this.height * ratio * this.reflectionScale,
    );
    if (!this.running || this.manual) this.render();
  }

  setRunning(on) {
    if (this.manual) return;
    if (on === this.running) return;
    this.running = on;
    cancelAnimationFrame(this.raf);
    if (on) {
      this.last = 0;
      this.raf = requestAnimationFrame(this.loop);
    }
  }

  /** Draws one frame without moving time, e.g. after a resize while paused. */
  render() {
    this.frame(0);
  }

  /** Hands the clock to the caller: `advance` then steps the scene and draws a frame. */
  setManual(on) {
    this.manual = on;
    cancelAnimationFrame(this.raf);
    this.running = false;
    if (!on) this.setRunning(true);
  }

  advance(dt) {
    this.frame(dt);
  }

  setScreen(state) {
    if (sameScreen(state, this.screenState)) return;
    const changedKind = state.kind !== this.screenState.kind;
    this.screenState = state;
    if (changedKind) this.screenSince = this.time;
    else this.screenSince = Math.min(this.screenSince, this.time - 0.33);
    if (state.kind === "error" && changedKind) this.shake = this.time;
    this.screenBusy = true;
  }

  /** A keystroke: one petal lets go of the branch, a key goes down, the branch nods. */
  keystroke(key) {
    this.sim.queueRelease(1);
    this.kickSpeed += 0.05;
    const name = key?.length === 1 ? (SHIFTED[key] ?? key.toLowerCase()) : key;
    let index = this.keys.findIndex((k) => k.char === name);
    if (index < 0)
      index = Math.abs(Math.floor(Math.sin(this.time * 97.3) * 1e4)) % this.keys.length;
    this.keys[index].at = this.time;
  }

  /** Success: a burst of petals, a gust across the lake and a ring around the stone. */
  celebrate() {
    this.sim.burst(40);
    this.kickSpeed += 0.55;
    this.cheer = this.time;
    const { stone } = PLACE;
    for (let k = 0; k < 4; k++) {
      const a = (k / 4) * TAU + 0.4;
      this.ripple(stone.x + Math.cos(a) * 0.15, stone.z + Math.sin(a) * 0.12, 2.2);
    }
  }

  /** The pointer over the scene, in normalised device coordinates, and how far it moved. */
  pointer(x, y, dx, dy, dt) {
    // While the caller steps the clock (a frame-by-frame capture), time between moves is scene time, not wall time.
    if (this.manual) dt = this.time - this.pointerTime;
    this.pointerTime = this.time;
    this.pointerAt.set(x, y);
    if (Math.abs(dx) + Math.abs(dy) < 1e-5) return;
    const cam = this.camera;
    const { vp, right, up } = this.tmp;
    vp.multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);
    right.setFromMatrixColumn(cam.matrixWorld, 0);
    up.setFromMatrixColumn(cam.matrixWorld, 1);
    this.sim.stir({
      x,
      y,
      dx,
      dy,
      dt,
      viewProjection: vp.elements,
      eye: cam.position,
      right,
      up,
      tanHalfFov: Math.tan((cam.fov * Math.PI) / 360),
      aspect: cam.aspect,
      radius: 0.48,
    });
  }

  stats() {
    const info = this.renderer.info.render;
    return {
      drawCalls: info.calls,
      triangles: info.triangles,
      petals: this.sim.active,
      frameMs: Math.round(this.frameMs * 10) / 10,
      cpuMs: Math.round(this.cpuMs * 100) / 100,
      ...this.qualityState(),
    };
  }

  dispose() {
    this.disposed = true;
    cancelAnimationFrame(this.raf);
    this.running = false;
    this.scene.traverse((object) => {
      if (object.geometry) object.geometry.dispose();
      const materials = Array.isArray(object.material)
        ? object.material
        : object.material
          ? [object.material]
          : [];
      for (const material of materials) {
        for (const value of Object.values(material)) if (value && value.isTexture) value.dispose();
        material.dispose();
      }
    });
    this.screenTexture.dispose();
    this.badgeTexture.dispose();
    this.mirror.dispose();
    this.sunLight.shadow.map?.dispose();
    this.renderer.dispose();
    this.renderer.forceContextLoss();
  }
}

// @zeus-internal
/**
 * The computer's screen, drawn on a 2D canvas that the scene turns into a texture. It follows the form: the logo
 * when idle, the email as it is typed, a dot per password character, progress, an error, then the welcome. A bright
 * line sweeps down on every change, the way an old tube redraws.
 */
import type { ScreenState } from "./form";

export interface ScreenCopy {
  brand: string;
  tagline: string;
  /** Labels above the echo while typing. */
  email: string;
  password: string;
  pending: string;
  welcome: string;
}

export interface ScreenColors {
  background: string;
  text: string;
  dim: string;
  /** The sun in the mark. */
  accent: string;
  error: string;
}

export const SCREEN_SIZE = { width: 512, height: 384 } as const;

const TAU = Math.PI * 2;
const clamp01 = (x: number) => Math.min(1, Math.max(0, x));
const ease = (x: number) => {
  const t = clamp01(x);
  return 1 - (1 - t) ** 3;
};

/** Sets the font at `size`, or smaller until `text` fits in `max`. */
function fit(ctx: CanvasRenderingContext2D, text: string, font: (size: number) => string, size: number, max: number) {
  ctx.font = font(size);
  const width = ctx.measureText(text).width;
  if (width > max) ctx.font = font(Math.max(10, Math.floor((size * max) / width)));
}

/** The mark: a sun disc over a horizon line. `rise` 0 sits the sun on the line, 1 lifts it clear. */
export function drawMark(
  ctx: CanvasRenderingContext2D,
  cx: number,
  cy: number,
  r: number,
  sun: string,
  line: string,
  rise = 0.7,
) {
  const lineY = cy + r * 0.62;
  const gap = Math.max(2, r * 0.16);
  ctx.save();
  ctx.beginPath();
  ctx.rect(cx - r * 3, cy - r * 4, r * 6, r * 4 + r * 0.62 - gap);
  ctx.clip();
  ctx.fillStyle = sun;
  ctx.beginPath();
  ctx.arc(cx, cy + (1 - rise) * r * 0.9, r, 0, TAU);
  ctx.fill();
  ctx.restore();
  ctx.fillStyle = line;
  const thick = Math.max(2, r * 0.15);
  ctx.beginPath();
  ctx.roundRect(cx - r * 1.55, lineY - thick / 2, r * 3.1, thick, thick / 2);
  ctx.fill();
}

function wrapLines(ctx: CanvasRenderingContext2D, text: string, width: number): string[] {
  const lines: string[] = [];
  let line = "";
  for (const word of text.split(/\s+/).filter(Boolean)) {
    const next = line ? `${line} ${word}` : word;
    if (ctx.measureText(next).width > width && line) {
      lines.push(line);
      line = word;
    } else line = next;
  }
  if (line) lines.push(line);
  return lines.slice(0, 3);
}

function glow(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, color: string, alpha: number) {
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, color);
  g.addColorStop(1, "transparent");
  ctx.globalAlpha = alpha;
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
  ctx.globalAlpha = 1;
}

/**
 * Draws one state. `since` is the seconds since the state began and `time` a running clock, both from the scene,
 * so a stepped clock draws the same frames every time.
 */
export function drawScreen(
  ctx: CanvasRenderingContext2D,
  state: ScreenState,
  since: number,
  time: number,
  copy: ScreenCopy,
  colors: ScreenColors,
  fonts: { sans: string; mono: string },
) {
  const { width: W, height: H } = SCREEN_SIZE;
  ctx.save();
  ctx.fillStyle = colors.background;
  ctx.fillRect(0, 0, W, H);
  ctx.textAlign = "center";
  ctx.textBaseline = "alphabetic";

  const caretOn = since < 0.6 || Math.floor(time * 1.8) % 2 === 0;
  const left = 54;
  const right = W - 54;

  switch (state.kind) {
    case "logo": {
      const rise = 0.62 + 0.08 * Math.sin(time * 0.5);
      glow(ctx, W / 2, 150, 150, colors.accent, 0.16);
      drawMark(ctx, W / 2, 148, 44, colors.accent, colors.text, rise);
      ctx.fillStyle = colors.text;
      fit(ctx, copy.brand, (px) => `600 ${px}px ${fonts.sans}`, 48, right - left);
      ctx.fillText(copy.brand, W / 2, 270);
      ctx.fillStyle = colors.dim;
      fit(ctx, copy.tagline, (px) => `400 ${px}px ${fonts.sans}`, 24, right - left);
      ctx.fillText(copy.tagline, W / 2, 310);
      break;
    }
    case "email":
    case "password": {
      ctx.textAlign = "left";
      ctx.fillStyle = colors.dim;
      ctx.font = `500 23px ${fonts.mono}`;
      ctx.fillText(state.kind === "email" ? copy.email : copy.password, left, 124);
      drawMark(ctx, right - 20, 104, 15, colors.accent, colors.dim, 0.7);
      ctx.fillStyle = colors.text;
      const baseline = 214;
      let end = left;
      if (state.kind === "email") {
        // Long addresses scroll, so the end being typed stays in view.
        ctx.font = `500 46px ${fonts.mono}`;
        const text = state.text;
        const width = ctx.measureText(text).width;
        const room = right - left - 30;
        ctx.save();
        ctx.beginPath();
        ctx.rect(left - 2, baseline - 56, right - left + 4, 76);
        ctx.clip();
        const shift = Math.max(0, width - room);
        ctx.fillText(text, left - shift, baseline);
        ctx.restore();
        end = left + Math.min(width, room) + 5;
      } else {
        const shown = Math.min(state.length, 12);
        for (let i = 0; i < shown; i++) {
          ctx.beginPath();
          ctx.arc(left + 13 + i * 32, baseline - 15, 10.5, 0, TAU);
          ctx.fill();
        }
        end = left + shown * 32 + 6;
      }
      if (caretOn) {
        ctx.fillStyle = colors.accent;
        ctx.fillRect(end, baseline - 40, 19, 50);
      }
      ctx.fillStyle = colors.dim;
      ctx.fillRect(left, baseline + 30, right - left, 3);
      break;
    }
    case "pending": {
      const pulse = 0.5 + 0.5 * Math.sin(time * 4);
      glow(ctx, W / 2, 132, 120, colors.accent, 0.1 + 0.08 * pulse);
      drawMark(ctx, W / 2, 130, 30, colors.accent, colors.text, 0.55 + 0.25 * pulse);
      ctx.fillStyle = colors.text;
      fit(ctx, copy.pending, (px) => `500 ${px}px ${fonts.sans}`, 34, right - left);
      ctx.fillText(copy.pending, W / 2, 240);
      const track = 280;
      const x0 = W / 2 - track / 2;
      ctx.fillStyle = colors.dim;
      ctx.globalAlpha = 0.45;
      ctx.beginPath();
      ctx.roundRect(x0, 272, track, 8, 4);
      ctx.fill();
      ctx.globalAlpha = 1;
      const head = (since * 0.9) % 1.4;
      const a = x0 + track * clamp01(head - 0.4);
      const b = x0 + track * clamp01(head);
      ctx.fillStyle = colors.accent;
      if (b - a > 1) {
        ctx.beginPath();
        ctx.roundRect(a, 272, b - a, 8, 4);
        ctx.fill();
      }
      break;
    }
    case "error": {
      ctx.strokeStyle = colors.error;
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.arc(W / 2, 112, 26, 0, TAU);
      ctx.stroke();
      ctx.fillStyle = colors.error;
      ctx.fillRect(W / 2 - 2.5, 98, 5, 18);
      ctx.beginPath();
      ctx.arc(W / 2, 125, 3.2, 0, TAU);
      ctx.fill();
      ctx.font = `500 34px ${fonts.sans}`;
      const lines = wrapLines(ctx, state.message, right - left);
      lines.forEach((line, i) => ctx.fillText(line, W / 2, 204 + i * 44));
      break;
    }
    case "welcome": {
      const rise = ease(since / 1.6);
      const text = ease((since - 0.45) / 0.9);
      glow(ctx, W / 2, 150, 120 + 90 * rise, colors.accent, 0.14 + 0.22 * rise);
      drawMark(ctx, W / 2, 150, 46, colors.accent, colors.text, 0.15 + 0.95 * rise);
      ctx.globalAlpha = text;
      ctx.fillStyle = colors.text;
      fit(ctx, copy.welcome, (px) => `600 ${px}px ${fonts.sans}`, 44, right - left + 30);
      ctx.fillText(copy.welcome, W / 2, 272 + (1 - text) * 14);
      ctx.globalAlpha = text * 0.9;
      ctx.fillStyle = colors.dim;
      fit(ctx, copy.tagline, (px) => `400 ${px}px ${fonts.sans}`, 24, right - left);
      ctx.fillText(copy.tagline, W / 2, 314 + (1 - text) * 14);
      ctx.globalAlpha = 1;
      break;
    }
  }

  // An error shakes the picture sideways in bands for a moment.
  if (state.kind === "error" && since < 0.5) {
    const strength = 1 - since / 0.5;
    const frame = Math.floor(since * 40);
    for (let band = 0; band < 6; band++) {
      const seed = Math.sin((frame + 1) * 12.9898 + band * 78.233) * 43758.5453;
      const r = seed - Math.floor(seed);
      const y = Math.floor(r * H);
      const h = 10 + Math.floor(r * 26);
      const shift = (r - 0.5) * 46 * strength;
      ctx.drawImage(ctx.canvas, 0, y, W, h, shift, y, W, h);
    }
  }

  // The redraw line: a soft bright band sweeping down after each change.
  if (since < 0.32) {
    const y = (since / 0.32) * (H + 60) - 30;
    const band = ctx.createLinearGradient(0, y - 30, 0, y + 30);
    band.addColorStop(0, "transparent");
    band.addColorStop(0.5, "rgba(255,255,255,0.22)");
    band.addColorStop(1, "transparent");
    ctx.fillStyle = band;
    ctx.fillRect(0, y - 30, W, 60);
  }
  ctx.restore();
}

/** Whether a state keeps moving, so the scene redraws it every frame rather than once. */
export const screenMoves = (state: ScreenState, since: number) =>
  state.kind === "pending" || state.kind === "logo" || since < 2 || state.kind === "email" || state.kind === "password";

// @zeus-internal
/**
 * The petals of the petal sign-up scene, with no three.js in it, so tests and the server can run it.
 *
 * A seeded pool of petals tumbles down a curl-noise wind. Each one lands on the water, the stone or the computer,
 * lies flat, drifts and fades, then falls again from above. A keystroke lets one petal go from a blossom on the
 * branch; a success shakes a burst loose and sends a gust across. The scene steps it at a fixed rate, so a seed
 * falls the same way on every machine. With no seed, each visit draws a new one.
 */

/** Seconds per simulation step. */
export const PETAL_STEP = 1 / 60;

export type Random = () => number;

/** Mulberry32: small, fast and plenty for petals. */
export function seededRandom(seed: number): Random {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** A new seed for each visit, from the platform's random source. */
export function freshSeed(): number {
  const source = globalThis.crypto;
  if (source && typeof source.getRandomValues === "function")
    return source.getRandomValues(new Uint32Array(1))[0] ?? 0;
  return Math.floor(Math.random() * 0xffffffff) >>> 0;
}

/** The seed a scene runs on: the one given, or a fresh one. */
export function resolveSeed(seed?: number): number {
  return seed === undefined || !Number.isFinite(seed)
    ? freshSeed()
    : Math.floor(Math.abs(seed)) >>> 0;
}

const TAU = Math.PI * 2;
const mix = (a: number, b: number, t: number) => a + (b - a) * t;
const fade = (t: number) => t * t * t * (t * (t * 6 - 15) + 10);
const smooth = (a: number, b: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};
/** An angle wrapped into -π…π. */
const wrap = (a: number) => a - TAU * Math.floor((a + Math.PI) / TAU);

function gradient(hash: number, x: number, y: number, z: number): number {
  const h = hash & 15;
  const u = h < 8 ? x : y;
  const v = h < 4 ? y : h === 12 || h === 14 ? x : z;
  return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
}

/** Gradient noise in three dimensions, roughly -1…1, on a seeded lattice. */
export class Noise3 {
  private readonly lattice = new Uint8Array(512);

  constructor(random: Random) {
    const order = new Uint8Array(256);
    for (let i = 0; i < 256; i++) order[i] = i;
    for (let i = 255; i > 0; i--) {
      const j = Math.floor(random() * (i + 1));
      const swap = order[i] ?? 0;
      order[i] = order[j] ?? 0;
      order[j] = swap;
    }
    for (let i = 0; i < 512; i++) this.lattice[i] = order[i & 255] ?? 0;
  }

  at(x: number, y: number, z: number): number {
    const p = this.lattice;
    const fx = Math.floor(x);
    const fy = Math.floor(y);
    const fz = Math.floor(z);
    const X = fx & 255;
    const Y = fy & 255;
    const Z = fz & 255;
    x -= fx;
    y -= fy;
    z -= fz;
    const u = fade(x);
    const v = fade(y);
    const w = fade(z);
    const A = (p[X] ?? 0) + Y;
    const AA = (p[A] ?? 0) + Z;
    const AB = (p[A + 1] ?? 0) + Z;
    const B = (p[X + 1] ?? 0) + Y;
    const BA = (p[B] ?? 0) + Z;
    const BB = (p[B + 1] ?? 0) + Z;
    return mix(
      mix(
        mix(gradient(p[AA] ?? 0, x, y, z), gradient(p[BA] ?? 0, x - 1, y, z), u),
        mix(gradient(p[AB] ?? 0, x, y - 1, z), gradient(p[BB] ?? 0, x - 1, y - 1, z), u),
        v,
      ),
      mix(
        mix(gradient(p[AA + 1] ?? 0, x, y, z - 1), gradient(p[BA + 1] ?? 0, x - 1, y, z - 1), u),
        mix(
          gradient(p[AB + 1] ?? 0, x, y - 1, z - 1),
          gradient(p[BB + 1] ?? 0, x - 1, y - 1, z - 1),
          u,
        ),
        v,
      ),
      w,
    );
  }
}

export interface Vec3 {
  x: number;
  y: number;
  z: number;
}

/** A wind with no sources or sinks: the curl of three noise fields, so petals swirl without bunching up. */
export class CurlWind {
  private readonly noise: Noise3;

  constructor(random: Random) {
    this.noise = new Noise3(random);
  }

  sample(x: number, y: number, z: number, out: Vec3): Vec3 {
    const n = this.noise;
    const e = 0.25;
    // Three potentials, offset from each other: a = n(p), b = n(p + B), c = n(p + C).
    const bx = x + 31.4;
    const by = y - 12.7;
    const bz = z + 7.3;
    const cx = x - 19.1;
    const cy = y + 41.9;
    const cz = z - 23.5;
    const dcdy = n.at(cx, cy + e, cz) - n.at(cx, cy - e, cz);
    const dbdz = n.at(bx, by, bz + e) - n.at(bx, by, bz - e);
    const dadz = n.at(x, y, z + e) - n.at(x, y, z - e);
    const dcdx = n.at(cx + e, cy, cz) - n.at(cx - e, cy, cz);
    const dbdx = n.at(bx + e, by, bz) - n.at(bx - e, by, bz);
    const dady = n.at(x, y + e, z) - n.at(x, y - e, z);
    const k = 1 / (2 * e);
    out.x = (dcdy - dbdz) * k;
    out.y = (dadz - dcdx) * k;
    out.z = (dbdx - dady) * k;
    return out;
  }
}

/*
 * The place, in metres. The water is the plane y = 0 and the camera looks down -z from in front.
 * Yaw turns about +y the way three.js does: a local (x, z) lands at (x cos + z sin, -x sin + z cos).
 */
export const PLACE = {
  stone: { x: 1.02, z: -0.22, radiusX: 1.12, radiusZ: 0.86, height: 0.32, yaw: -0.16 },
  computer: { x: 0.67, z: -0.16, yaw: -0.45, scale: 1.18 },
} as const;

/** Where the petals fall from and how far they may travel. */
export const BOUNDS = {
  x0: -2.6,
  x1: 2.4,
  z0: -3.0,
  z1: 1.5,
  top: 1.4,
  spread: 1.0,
  east: 3.0,
} as const;

/** The breeze: from the canopy on the right to the open lake on the left, slightly towards the camera. */
const DIR_X = -0.99;
const DIR_Z = 0.12;
const FLOAT_Y = 0.0035;
const REST_Y = 0.004;

const toLocal = (x: number, z: number, ox: number, oz: number, yaw: number): [number, number] => {
  const dx = x - ox;
  const dz = z - oz;
  const c = Math.cos(yaw);
  const s = Math.sin(yaw);
  return [dx * c - dz * s, dx * s + dz * c];
};
const toWorld = (lx: number, lz: number, ox: number, oz: number, yaw: number): [number, number] => {
  const c = Math.cos(yaw);
  const s = Math.sin(yaw);
  return [ox + lx * c + lz * s, oz - lx * s + lz * c];
};

const STONE_GRAIN = new Noise3(seededRandom(0x51a7e));

/** Displaced granite ledge. The mesh, seating and petal collisions sample this same surface. */
export function stoneHeight(x: number, z: number): number {
  const { stone } = PLACE;
  const [lx, lz] = toLocal(x, z, stone.x, stone.z, stone.yaw);
  const angle = Math.atan2(lz, lx);
  const outline =
    1 +
    0.07 * Math.sin(angle * 3 + 0.7) +
    0.045 * Math.sin(angle * 5 + 2.1) +
    0.022 * Math.sin(angle * 11);
  const r = Math.hypot(lx / stone.radiusX, lz / stone.radiusZ) / outline;
  if (r >= 1) return -0.4 * (r - 1) - 0.002;
  // A broad platform ends in fractured, steep faces instead of rolling into a pebble.
  const shoulder = 0.79 + STONE_GRAIN.at(x * 5, 0.9, z * 5) * 0.065;
  const profile = 1 - smooth(shoulder, 1, r);
  const grain =
    STONE_GRAIN.at(x * 4.1, 0.37, z * 4.1) * 0.052 +
    STONE_GRAIN.at(x * 17.3, 1.7, z * 17.3) * 0.018;
  const fracture = Math.abs(STONE_GRAIN.at(x * 12, 2.3, z * 12)) * 0.035;
  return (stone.height + grain - fracture) * profile;
}

export interface Part {
  /** The footprint in the computer's frame: x to its right, z out of its screen. */
  x0: number;
  x1: number;
  z0: number;
  z1: number;
  /** World height of its top. */
  top: number;
}

/** The support height under a rigid footprint; its feet sit on the high granite points instead of sinking into them. */
function seat(x0: number, x1: number, z0: number, z1: number): number {
  let support = -Infinity;
  for (let i = 0; i <= 4; i++)
    for (let j = 0; j <= 4; j++) {
      const [x, z] = toWorld(
        mix(x0, x1, i / 4) * PLACE.computer.scale,
        mix(z0, z1, j / 4) * PLACE.computer.scale,
        PLACE.computer.x,
        PLACE.computer.z,
        PLACE.computer.yaw,
      );
      support = Math.max(support, stoneHeight(x, z));
    }
  return support;
}

const BASE = seat(-0.29, 0.29, -0.25, 0.25) - 0.004;
const keyboardBase = seat(-0.235, 0.235, 0.34, 0.5) - 0.002;

/** The computer's parts, which petals settle on and blow around. The scene builds its meshes to the same sizes. */
export const PARTS = {
  base: BASE,
  keyboardBase,
  unit: { x0: -0.29, x1: 0.29, z0: -0.25, z1: 0.25, top: BASE + 0.1 * PLACE.computer.scale },
  monitor: { x0: -0.255, x1: 0.255, z0: -0.25, z1: 0.205, top: BASE + 0.53 * PLACE.computer.scale },
  tube: { x0: -0.18, x1: 0.18, z0: -0.45, z1: -0.25, top: BASE + 0.47 * PLACE.computer.scale },
  keyboard: {
    x0: -0.235,
    x1: 0.235,
    z0: 0.34,
    z1: 0.5,
    top: keyboardBase + 0.034 * PLACE.computer.scale,
  },
} as const;
const SOLIDS: Part[] = [PARTS.unit, PARTS.monitor, PARTS.tube, PARTS.keyboard].map((p) => ({
  ...p,
  x0: p.x0 * PLACE.computer.scale,
  x1: p.x1 * PLACE.computer.scale,
  z0: p.z0 * PLACE.computer.scale,
  z1: p.z1 * PLACE.computer.scale,
}));

const IDLE = 0;
const FALLING = 1;
const AFLOAT = 2;
const RESTING = 3;
export const PETAL_MODES = { IDLE, FALLING, AFLOAT, RESTING } as const;

const WATER = 0;
const STONE = 1;
const SOLID = 2;

export interface PetalSimOptions {
  seed: number;
  /** Petals in the air and on the water at once. */
  count: number;
  /** Extra petals for keystrokes and bursts. */
  spare?: number;
  /** Multiplies the breeze and its eddies. */
  wind?: number;
  /** Blossoms petals are let go from, as x, y, z triples. The scene keeps them current as the branch sways. */
  blossoms?: Float32Array;
}

/** A pointer stirring the air, in the camera's normalised device coordinates. */
export interface Stir {
  x: number;
  y: number;
  /** Movement since the last event. */
  dx: number;
  dy: number;
  /** Seconds since the last event. */
  dt: number;
  /** The camera's view-projection matrix, column-major. */
  viewProjection: ArrayLike<number>;
  eye: Vec3;
  right: Vec3;
  up: Vec3;
  tanHalfFov: number;
  aspect: number;
  /** Reach, as a share of the view's height. */
  radius?: number;
}

/** A blossom cluster on a branch, in default positions until the scene supplies its own. */
const DEFAULT_BLOSSOMS = new Float32Array([
  0.9, 1.7, 0.5, 0.6, 1.62, 0.45, 1.2, 1.85, 0.6, 0.3, 1.55, 0.4,
]);

export class PetalSim {
  readonly count: number;
  readonly capacity: number;
  readonly x: Float32Array;
  readonly y: Float32Array;
  readonly z: Float32Array;
  readonly vx: Float32Array;
  readonly vy: Float32Array;
  readonly vz: Float32Array;
  /** Orientation as XYZ Euler angles. */
  readonly rx: Float32Array;
  readonly ry: Float32Array;
  readonly rz: Float32Array;
  readonly size: Float32Array;
  /** 0…1 per petal: how far its colour leans from pink to white. */
  readonly tint: Float32Array;
  readonly alpha: Float32Array;
  /** 0…1: how long it has been in the water. */
  readonly wet: Float32Array;
  readonly mode: Uint8Array;
  time = 0;
  wind: number;
  /** The share of petals kept falling; the scene thins them when frames run long. */
  density = 1;
  pendingReleases = 0;
  /** 0…1, the strength of the current gust. */
  gust = 0;
  blossoms: Float32Array;

  private readonly spinX: Float32Array;
  private readonly spinY: Float32Array;
  private readonly spinZ: Float32Array;
  /** Extra tumble from a stir, fading back to the petal's own spin. */
  private readonly kick: Float32Array;
  private readonly phase: Float32Array;
  private readonly flutter: Float32Array;
  private readonly sway: Float32Array;
  private readonly fall: Float32Array;
  private readonly age: Float32Array;
  private readonly life: Float32Array;
  private readonly settleX: Float32Array;
  private readonly settleY: Float32Array;
  private readonly fallRandom: Random;
  private readonly releaseRandom: Random;
  private readonly air: CurlWind;
  private readonly landings: number[] = [];
  private readonly sample: Vec3 = { x: 0, y: 0, z: 0 };
  private order: Uint16Array;
  private released = 0;
  private burstPending = 0;
  private gustTarget = 0;

  constructor(options: PetalSimOptions) {
    const seed = options.seed >>> 0;
    this.count = Math.max(0, Math.floor(options.count));
    this.capacity = this.count + Math.max(1, Math.floor(options.spare ?? 72));
    this.wind = options.wind ?? 1;
    this.fallRandom = seededRandom(seed);
    this.releaseRandom = seededRandom(seed ^ 0x9e3779b9);
    this.air = new CurlWind(seededRandom((seed + 0x632be5ab) >>> 0));
    const n = this.capacity;
    const f = () => new Float32Array(n);
    this.x = f();
    this.y = f();
    this.z = f();
    this.vx = f();
    this.vy = f();
    this.vz = f();
    this.rx = f();
    this.ry = f();
    this.rz = f();
    this.size = f();
    this.tint = f();
    this.alpha = f();
    this.wet = f();
    this.spinX = f();
    this.spinY = f();
    this.spinZ = f();
    this.kick = f();
    this.phase = f();
    this.flutter = f();
    this.sway = f();
    this.fall = f();
    this.age = f();
    this.life = f();
    this.settleX = f();
    this.settleY = f();
    this.mode = new Uint8Array(n);
    this.blossoms = options.blossoms ?? DEFAULT_BLOSSOMS;
    this.order = this.shuffle(this.blossoms.length / 3);

    // Start mid-fall: most petals in the air, some already on the water at every stage of fading.
    const r = this.fallRandom;
    for (let i = 0; i < this.count; i++) {
      if (i % 7 === 0) this.spawnResting(i);
      else if (r() < 0.34) this.spawnAfloat(i);
      else this.spawnHigh(i, true);
    }
  }

  /** Blossom positions to let petals go from, as x, y, z triples. */
  setBlossoms(positions: Float32Array) {
    const before = this.blossoms.length;
    this.blossoms = positions;
    if (positions.length !== before) this.order = this.shuffle(positions.length / 3);
  }

  /** Lets one petal go from the branch on the next step. */
  queueRelease(count = 1) {
    this.pendingReleases += Math.max(0, Math.floor(count));
  }

  /** Shakes a burst of petals loose and sends a gust across. */
  burst(count = 36) {
    this.burstPending += Math.max(0, Math.floor(count));
    this.gustTarget = 1;
  }

  /** Petals in the air, on the water or on the stone. */
  get active(): number {
    let n = 0;
    for (let i = 0; i < this.capacity; i++) if (this.mode[i] !== IDLE) n++;
    return n;
  }

  /** Hands over each water landing since the last call, for a ripple. */
  drainLandings(take: (x: number, z: number, strength: number) => void) {
    const list = this.landings;
    for (let i = 0; i < list.length; i += 3) take(list[i] ?? 0, list[i + 1] ?? 0, list[i + 2] ?? 0);
    list.length = 0;
  }

  step(dt = PETAL_STEP) {
    this.time += dt;
    this.gustTarget *= Math.exp(-dt / 1.25);
    this.gust += (this.gustTarget - this.gust) * (1 - Math.exp(-dt * 4.5));
    while (this.pendingReleases > 0) {
      this.pendingReleases--;
      this.letGo(false);
    }
    while (this.burstPending > 0) {
      this.burstPending--;
      this.letGo(true);
    }
    const live = this.live();
    for (let i = 0; i < this.capacity; i++) {
      const mode = this.mode[i];
      if (mode === FALLING) this.fly(i, dt);
      else if (mode === AFLOAT) this.drift(i, dt);
      else if (mode === RESTING) this.rest(i, dt);
      else if (i < live) this.spawnHigh(i, false);
    }
  }

  /** Pushes the petals near the pointer along with it. */
  stir(s: Stir) {
    const m = s.viewProjection;
    const reach = s.radius ?? 0.48;
    const step = Math.max(s.dt, 1 / 240);
    const sx = (s.dx / step) * s.aspect;
    const sy = s.dy / step;
    const m0 = m[0] ?? 0;
    const m1 = m[1] ?? 0;
    const m3 = m[3] ?? 0;
    const m4 = m[4] ?? 0;
    const m5 = m[5] ?? 0;
    const m7 = m[7] ?? 0;
    const m8 = m[8] ?? 0;
    const m9 = m[9] ?? 0;
    const m11 = m[11] ?? 0;
    const m12 = m[12] ?? 0;
    const m13 = m[13] ?? 0;
    const m15 = m[15] ?? 0;
    for (let i = 0; i < this.capacity; i++) {
      const mode = this.mode[i];
      if (mode !== FALLING && mode !== AFLOAT && mode !== RESTING) continue;
      const x = this.x[i] ?? 0;
      const y = this.y[i] ?? 0;
      const z = this.z[i] ?? 0;
      const w = m3 * x + m7 * y + m11 * z + m15;
      if (w <= 0.05) continue;
      const nx = (m0 * x + m4 * y + m8 * z + m12) / w;
      const ny = (m1 * x + m5 * y + m9 * z + m13) / w;
      const ox = (nx - s.x) * s.aspect;
      const oy = ny - s.y;
      const d = Math.hypot(ox, oy);
      if (d >= reach) continue;
      const u = 1 - d / reach;
      const near = u * u * (3 - 2 * u);
      // The pointer's speed at the petal's depth, in metres a second, plus a nudge out of its way.
      const metres = Math.hypot(x - s.eye.x, y - s.eye.y, z - s.eye.z) * s.tanHalfFov;
      const away = d > 1e-4 ? Math.min(Math.hypot(sx, sy), 6) * 0.18 : 0;
      const px = sx + (d > 1e-4 ? (ox / d) * away : 0);
      const py = sy + (d > 1e-4 ? (oy / d) * away : 0);
      // On the lake a vertical screen sweep travels across the surface, not into it.
      const landed = mode !== FALLING;
      let wx = (s.right.x * px + (landed ? s.right.z : s.up.x) * py) * metres * 1.35;
      let wy = landed ? 0 : (s.right.y * px + s.up.y * py) * metres * 1.35;
      let wz = (s.right.z * px + (landed ? -s.right.x : s.up.z) * py) * metres * 1.35;
      const speed = Math.hypot(wx, wy, wz);
      if (speed > 3) {
        wx *= 3 / speed;
        wy *= 3 / speed;
        wz *= 3 / speed;
      }
      // Exponential response is independent of pointer event rate, with no position jumps.
      const pull = 1 - Math.exp(-near * 24 * Math.min(step, 0.05));
      this.vx[i] = (this.vx[i] ?? 0) + (wx - (this.vx[i] ?? 0)) * pull;
      this.vz[i] = (this.vz[i] ?? 0) + (wz - (this.vz[i] ?? 0)) * pull;
      if (mode === FALLING) {
        this.vy[i] = (this.vy[i] ?? 0) + (wy - (this.vy[i] ?? 0)) * pull;
        if (speed > 0.2) this.kick[i] = Math.min(9, (this.kick[i] ?? 0) + near * 2.4);
      } else if (mode === RESTING && speed * near > 0.12) {
        // Dry petals lift from their current contact point; the normal fall handles the landing.
        this.mode[i] = FALLING;
        this.vy[i] = 0.2 + near * 0.35;
        this.kick[i] = near * 2.4;
      }
    }
  }

  private live(): number {
    return Math.round(this.count * Math.min(1, Math.max(0, this.density)));
  }

  private shuffle(n: number): Uint16Array {
    const order = new Uint16Array(Math.max(1, Math.floor(n)));
    for (let i = 0; i < order.length; i++) order[i] = i;
    const r = this.releaseRandom;
    for (let i = order.length - 1; i > 0; i--) {
      const j = Math.floor(r() * (i + 1));
      const swap = order[i] ?? 0;
      order[i] = order[j] ?? 0;
      order[j] = swap;
    }
    return order;
  }

  /** Orientation, spin, flutter, size and colour for a petal starting out. */
  private dress(i: number, r: Random) {
    this.rx[i] = r() * TAU;
    this.ry[i] = r() * TAU;
    this.rz[i] = r() * TAU;
    this.spinX[i] = (r() - 0.5) * 5.2;
    this.spinY[i] = (r() - 0.5) * 2.2;
    this.spinZ[i] = (r() - 0.5) * 4.2;
    this.kick[i] = 0;
    this.phase[i] = r() * TAU;
    this.flutter[i] = mix(2.3, 4.6, r());
    this.sway[i] = mix(0.1, 0.3, r());
    this.fall[i] = mix(0.3, 0.52, r());
    this.size[i] = mix(0.75, 1.25, r());
    this.tint[i] = r();
    this.age[i] = 0;
    this.life[i] = 0;
    this.alpha[i] = 1;
    this.wet[i] = 0;
  }

  private spawnHigh(i: number, anywhere: boolean) {
    const r = this.fallRandom;
    // Ambient fall uses the same real blossom sites as keystrokes and success. Never an arbitrary sky box.
    const b = Math.floor(r() * (this.blossoms.length / 3)) * 3;
    this.dress(i, r);
    this.mode[i] = FALLING;
    this.x[i] = (this.blossoms[b] ?? 0) + (r() - 0.5) * 0.025;
    this.y[i] = (this.blossoms[b + 1] ?? 1.5) - 0.018;
    this.z[i] = (this.blossoms[b + 2] ?? 0) + (r() - 0.5) * 0.025;
    this.vx[i] = DIR_X * 0.16 * this.wind;
    this.vy[i] = -0.16;
    this.vz[i] = DIR_Z * 0.16 * this.wind;
    if (anywhere) {
      // A deterministic warm start along a fall from that blossom, never above/outside the canopy.
      const age = r() * 3.7;
      this.x[i] += DIR_X * 0.22 * this.wind * age;
      this.z[i] += DIR_Z * 0.22 * this.wind * age;
      this.y[i] -= (this.fall[i] ?? 0.4) * 0.85 * age;
      const ground = this.ground(this.x[i] ?? 0, this.z[i] ?? 0);
      if ((this.y[i] ?? 0) <= ground.height + REST_Y) {
        this.y[i] = ground.height;
        this.settle(i, ground.kind === WATER ? AFLOAT : RESTING);
      }
    }
  }

  private spawnResting(i: number) {
    const r = this.fallRandom;
    this.dress(i, r);
    const a = r() * TAU,
      radius = 0.3 + r() * 0.53;
    const x = PLACE.stone.x + Math.cos(a) * PLACE.stone.radiusX * radius;
    const z = PLACE.stone.z + Math.sin(a) * PLACE.stone.radiusZ * radius;
    const ground = this.ground(x, z);
    this.x[i] = x;
    this.z[i] = z;
    this.y[i] = ground.height;
    this.settle(i, ground.kind === WATER ? AFLOAT : RESTING);
    this.age[i] = r() * 2;
  }

  private spawnAfloat(i: number) {
    const r = this.fallRandom;
    this.dress(i, r);
    let x = mix(-1.6, 2.1, r());
    let z = r() < 0.75 ? mix(0.25, 1.45, r()) : mix(-2.6, -1.1, r());
    if (stoneHeight(x, z) > -0.03) [x, z] = this.offStone(x, z, 0.12);
    this.x[i] = x;
    this.z[i] = z;
    this.y[i] = FLOAT_Y;
    this.vx[i] = DIR_X * 0.02;
    this.vy[i] = 0;
    this.vz[i] = 0;
    this.mode[i] = AFLOAT;
    this.life[i] = mix(7, 11, r());
    this.age[i] = r() * (this.life[i] ?? 0) * 0.85;
    this.rx[i] = r() < 0.5 ? Math.PI / 2 : -Math.PI / 2;
    this.ry[i] = 0;
    this.settleX[i] = this.rx[i] ?? 0;
    this.settleY[i] = 0;
    this.wet[i] = 1;
  }

  /** The point just outside the stone's rim along the line from its centre. */
  private offStone(x: number, z: number, margin: number): [number, number] {
    const { stone } = PLACE;
    let dx = x - stone.x;
    let dz = z - stone.z;
    const length = Math.hypot(dx, dz) || 1;
    dx /= length;
    dz /= length;
    let reach = length;
    for (let k = 0; k < 24 && stoneHeight(stone.x + dx * reach, stone.z + dz * reach) > -0.01; k++)
      reach += 0.05;
    return [stone.x + dx * (reach + margin), stone.z + dz * (reach + margin)];
  }

  private letGo(burst: boolean) {
    let slot = -1;
    let oldest = -1;
    let oldestAge = -1;
    for (let i = this.count; i < this.capacity; i++) {
      if (this.mode[i] === IDLE) {
        slot = i;
        break;
      }
      const age = this.age[i] ?? 0;
      if (this.mode[i] !== FALLING && age > oldestAge) {
        oldestAge = age;
        oldest = i;
      }
    }
    if (slot < 0)
      slot = oldest >= 0 ? oldest : this.count + (this.released % (this.capacity - this.count));
    const r = this.releaseRandom;
    const sites = this.blossoms.length / 3;
    const site = this.order[this.released % Math.max(1, this.order.length)] ?? 0;
    this.released++;
    const b = (site % Math.max(1, sites)) * 3;
    this.dress(slot, r);
    this.mode[slot] = FALLING;
    this.x[slot] = (this.blossoms[b] ?? 0) + (r() - 0.5) * 0.04;
    this.y[slot] = (this.blossoms[b + 1] ?? 0) - 0.02;
    this.z[slot] = (this.blossoms[b + 2] ?? 0) + (r() - 0.5) * 0.04;
    this.vx[slot] = DIR_X * (burst ? mix(0.2, 1.2, r()) : mix(0.08, 0.22, r()));
    this.vy[slot] = burst ? mix(-0.6, 0.5, r()) : -0.12;
    this.vz[slot] = burst ? mix(-0.7, 0.9, r()) : mix(-0.15, 0.15, r());
  }

  private ground(x: number, z: number): { height: number; kind: number; part: Part | null } {
    let height = 0;
    let kind = WATER;
    let part: Part | null = null;
    const stone = stoneHeight(x, z);
    if (stone > 0.002) {
      height = stone;
      kind = STONE;
    }
    const { computer } = PLACE;
    const [lx, lz] = toLocal(x, z, computer.x, computer.z, computer.yaw);
    for (const solid of SOLIDS) {
      if (lx > solid.x0 && lx < solid.x1 && lz > solid.z0 && lz < solid.z1 && solid.top > height) {
        height = solid.top;
        kind = SOLID;
        part = solid;
      }
    }
    return { height, kind, part };
  }

  private fly(i: number, dt: number) {
    const w = this.wind;
    const gust = this.gust;
    let x = this.x[i] ?? 0;
    let y = this.y[i] ?? 0;
    let z = this.z[i] ?? 0;
    const before = y;
    const c = this.air.sample(
      x * 0.42,
      y * 0.42 + this.time * 0.05,
      z * 0.42 - this.time * 0.03,
      this.sample,
    );
    const breeze = (0.32 + 0.95 * gust) * w;
    const eddy = (0.12 + 0.25 * gust) * w;
    const phase = (this.phase[i] ?? 0) + (this.flutter[i] ?? 0) * dt;
    this.phase[i] = phase;
    // A falling leaf: it swings side to side and slows at the top of each swing.
    const swing = (this.sway[i] ?? 0) * Math.cos(phase);
    const heading = this.ry[i] ?? 0;
    const tx = breeze * DIR_X + c.x * eddy + swing * Math.cos(heading);
    const tz = breeze * DIR_Z + c.z * eddy + swing * Math.sin(heading);
    const ty =
      -(this.fall[i] ?? 0) * (0.72 + 0.56 * Math.abs(Math.sin(phase))) +
      c.y * eddy * 0.5 +
      gust * 0.32 * w;
    const k = 1 - Math.exp(-2.4 * dt);
    let vx = (this.vx[i] ?? 0) + (tx - (this.vx[i] ?? 0)) * k;
    let vy = (this.vy[i] ?? 0) + (ty - (this.vy[i] ?? 0)) * k;
    let vz = (this.vz[i] ?? 0) + (tz - (this.vz[i] ?? 0)) * k;
    x += vx * dt;
    y += vy * dt;
    z += vz * dt;
    const kick = this.kick[i] ?? 0;
    this.rx[i] =
      (this.rx[i] ?? 0) + ((this.spinX[i] ?? 0) + kick + c.z * 1.4 + Math.cos(phase) * 0.9) * dt;
    this.ry[i] = (this.ry[i] ?? 0) + (this.spinY[i] ?? 0) * dt;
    this.rz[i] = (this.rz[i] ?? 0) + ((this.spinZ[i] ?? 0) - c.x * 1.4 + kick * 0.5) * dt;
    this.kick[i] = kick * Math.exp(-1.6 * dt);

    const g = this.ground(x, z);
    if (y <= g.height + REST_Y) {
      if (g.kind === WATER) {
        this.store(i, x, g.height, z, vx, vy, vz);
        this.settle(i, AFLOAT);
        return;
      }
      if (g.kind === SOLID && g.part && before < g.part.top - 0.025) {
        // Blown against the computer's side: slide off it instead of jumping onto it.
        const { computer } = PLACE;
        const [lx, lz] = toLocal(x, z, computer.x, computer.z, computer.yaw);
        const p = g.part;
        const gaps = [lx - p.x0, p.x1 - lx, lz - p.z0, p.z1 - lz];
        const nearest = gaps.indexOf(Math.min(...gaps));
        const ex = nearest === 0 ? p.x0 - 0.01 : nearest === 1 ? p.x1 + 0.01 : lx;
        const ez = nearest === 2 ? p.z0 - 0.01 : nearest === 3 ? p.z1 + 0.01 : lz;
        [x, z] = toWorld(ex, ez, computer.x, computer.z, computer.yaw);
        vx *= -0.2;
        vz *= -0.2;
      } else if (g.kind === STONE && (before < g.height - 0.04 || this.steep(x, z))) {
        // Under the rim, or on its steep shoulder: slide off toward the water.
        const { stone } = PLACE;
        const dx = x - stone.x;
        const dz = z - stone.z;
        const length = Math.hypot(dx, dz) || 1;
        x += (dx / length) * 0.02;
        z += (dz / length) * 0.02;
        y = Math.max(y, g.height + REST_Y);
        vx = (dx / length) * 0.25;
        vz = (dz / length) * 0.25;
        vy = Math.min(vy, -0.2);
      } else {
        this.store(i, x, g.height, z, vx, vy, vz);
        this.settle(i, RESTING);
        return;
      }
    }
    this.store(i, x, y, z, vx, vy, vz);
    if (
      x > BOUNDS.east ||
      x < BOUNDS.x0 - 1.5 ||
      z < BOUNDS.z0 - 1 ||
      z > BOUNDS.z1 + 0.8 ||
      y < -0.5
    )
      this.finish(i);
  }

  private steep(x: number, z: number): boolean {
    const e = 0.03;
    const gx = (stoneHeight(x + e, z) - stoneHeight(x - e, z)) / (2 * e);
    const gz = (stoneHeight(x, z + e) - stoneHeight(x, z - e)) / (2 * e);
    return Math.hypot(gx, gz) > 1.15;
  }

  private store(i: number, x: number, y: number, z: number, vx: number, vy: number, vz: number) {
    this.x[i] = x;
    this.y[i] = y;
    this.z[i] = z;
    this.vx[i] = vx;
    this.vy[i] = vy;
    this.vz[i] = vz;
  }

  private settle(i: number, mode: number) {
    const r = this.fallRandom;
    this.mode[i] = mode;
    this.y[i] = (this.y[i] ?? 0) + (mode === AFLOAT ? FLOAT_Y : REST_Y);
    this.vx[i] = (this.vx[i] ?? 0) * 0.3;
    this.vz[i] = (this.vz[i] ?? 0) * 0.3;
    this.vy[i] = 0;
    this.age[i] = 0;
    this.life[i] = mode === AFLOAT ? mix(7, 11, r()) : mix(9, 15, r());
    // Lie flat, face up or face down, whichever is nearer; the turn in the plane is kept.
    const rx = wrap(this.rx[i] ?? 0);
    const ry = wrap(this.ry[i] ?? 0);
    this.rx[i] = rx;
    this.ry[i] = ry;
    this.settleX[i] = rx >= 0 ? Math.PI / 2 : -Math.PI / 2;
    this.settleY[i] = Math.abs(ry) < Math.PI / 2 ? 0 : ry > 0 ? Math.PI : -Math.PI;
    if (mode === AFLOAT)
      this.landings.push(
        this.x[i] ?? 0,
        this.z[i] ?? 0,
        mix(0.55, 1, ((this.size[i] ?? 1) - 0.75) / 0.5),
      );
  }

  private lieFlat(i: number, dt: number) {
    const k = 1 - Math.exp(-7 * dt);
    this.rx[i] = (this.rx[i] ?? 0) + ((this.settleX[i] ?? 0) - (this.rx[i] ?? 0)) * k;
    this.ry[i] = (this.ry[i] ?? 0) + ((this.settleY[i] ?? 0) - (this.ry[i] ?? 0)) * k;
  }

  private drift(i: number, dt: number) {
    const age = (this.age[i] ?? 0) + dt;
    this.age[i] = age;
    this.lieFlat(i, dt);
    this.rz[i] = (this.rz[i] ?? 0) + (this.spinY[i] ?? 0) * 0.1 * dt;
    const current = (0.03 + 0.14 * this.gust) * this.wind;
    const k = 1 - Math.exp(-0.8 * dt);
    const vx = (this.vx[i] ?? 0) + (current * DIR_X - (this.vx[i] ?? 0)) * k;
    const vz = (this.vz[i] ?? 0) + (current * DIR_Z - (this.vz[i] ?? 0)) * k;
    let x = (this.x[i] ?? 0) + vx * dt;
    let z = (this.z[i] ?? 0) + vz * dt;
    if (stoneHeight(x, z) > -0.015) [x, z] = this.offStone(x, z, 0.02);
    this.x[i] = x;
    this.z[i] = z;
    this.vx[i] = vx;
    this.vz[i] = vz;
    const life = this.life[i] ?? 1;
    this.wet[i] = Math.min(1, age / 3);
    this.alpha[i] = 1 - smooth(life - 2.6, life, age);
    if (age >= life || x > BOUNDS.east + 1) this.finish(i);
  }

  private rest(i: number, dt: number) {
    const age = (this.age[i] ?? 0) + dt;
    this.age[i] = age;
    this.lieFlat(i, dt);
    // A strong gust lifts petals off the stone and the computer.
    if (this.gust > 0.5 && (this.tint[i] ?? 0) < this.gust - 0.25) {
      this.mode[i] = FALLING;
      this.vx[i] = DIR_X * (0.9 + (this.tint[i] ?? 0) * 0.8);
      this.vy[i] = 0.5 + (this.size[i] ?? 1) * 0.3;
      this.vz[i] = 0.2;
      this.y[i] = (this.y[i] ?? 0) + 0.01;
      return;
    }
    const life = this.life[i] ?? 1;
    this.alpha[i] = 1 - smooth(life - 2.2, life, age);
    if (age >= life) this.finish(i);
  }

  private finish(i: number) {
    if (i < this.live()) this.spawnHigh(i, false);
    else {
      this.mode[i] = IDLE;
      this.alpha[i] = 0;
    }
  }
}

