.zps-provider{display:flex;align-items:center;justify-content:center;gap:8px;min-width:0;height:44px;padding:0 10px;border:1px solid var(--zps-line);border-radius:12px;background:var(--zps-field);color:var(--zps-ink);font:inherit;font-size:14px;font-weight:600;cursor:pointer;transition:border-color .16s,background-color .16s}
.zps-provider:hover{border-color:color-mix(in srgb,var(--zps-ink) 26%,var(--zps-line))}
.zps-provider svg{flex:none;width:18px;height:18px}
.zps-provider span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.zps-provider:disabled{opacity:.55;cursor:default}
.zps-switch{width:100%;max-width:400px;align-self:center;margin:0;font-size:14px;color:var(--zps-muted)}
.zps-done{display:flex;flex-direction:column;align-items:flex-start;align-self:start;gap:14px}
.zps-done p{margin:0;font-size:15px;line-height:1.55;color:var(--zps-muted)}
.zps-done strong{color:var(--zps-ink);font-weight:650;overflow-wrap:anywhere}
.zps-again{height:40px;padding:0 14px;border:1px solid var(--zps-line);border-radius:10px;background:var(--zps-field);color:var(--zps-ink);font:inherit;font-size:14px;font-weight:600;cursor:pointer}
.zps button:focus-visible,.zps a:focus-visible,.zps-check:focus-visible{outline:2px solid var(--zps-focus);outline-offset:2px}
.zps-title:focus-visible{outline:2px solid var(--zps-focus);outline-offset:4px;border-radius:4px}
.zps-scene{position:relative;min-width:0;min-height:300px;overflow:hidden;border-radius:20px;background:var(--zps-backdrop);isolation:isolate}
.zps-poster,.zps-canvas{position:absolute;inset:0;width:100%;height:100%}
.zps-poster svg,.zps-poster img{display:block;width:100%;height:100%;object-fit:cover}
.zps-canvas{display:block;opacity:0;transition:opacity .9s ease}
.zps[data-scene=live] .zps-canvas{opacity:1}
.zps-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
@container (max-width:640px){
.zps-card{grid-template-columns:minmax(0,1fr);min-height:0;padding:8px;border-radius:24px}
.zps-scene{order:-1;min-height:0;height:clamp(220px,77cqi,340px);border-radius:18px}
.zps-side{gap:22px;padding:22px 16px 20px}
.zps-main{max-width:none}
.zps-title{font-size:26px}
}
@media (prefers-reduced-motion:reduce){
.zps-canvas,.zps-input,.zps-check,.zps-check::after,.zps-submit{transition:none}
.zps-spinner{animation-duration:2.4s}
}
`;
